quests[27125] = { id = 27125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Gordok", description = "In Gordok society, their king is simply their strongest warrior. If anyone, ogre or otherwise, kills the current king, they are automatically hailed as the new one.\n\nThe new king receives tribute from any living guards, Stomper Kreeg, and Captain Kromcrush. Find and kill King Gordok while killing as few of their other leaders as possible, and not only will your reward be great, you will be able to use your power as king to halt the Gordok invasion without conflict!", sourceObjective = "Kill King Gordok.", progress = "I have faith that you will be able to complete the task set out before you.", completion = "Yes! I can see that you were indeed successful. You have received your tribute, the Gordok advance will exist no longer, and the Gordok are blissfully ignorant! This is a true winner's scenario, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27126] = { id = 27126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rush Delivery", description = "Peak Grindstone's team broke down somewhere out there to the west.\n\nThink you can make yourself useful for a change and rush some parts out to them, {race}?", sourceObjective = "Deliver the Catapult Parts to Peak Grindstone on the Fractured Front in Deepholm.", progress = "Are those spare parts you have there?", completion = "I can't thank you enough, {class}. Now, let's see if we can get this catapult moving again.", sourceObjectiveStatus = "unverified-source-field" }
quests[27127] = { id = 27127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fired Up and Not So Good To Go.", description = "Dark Irons? Cho'gall?! We'll show them what becomes of those who attack Orgrimmar.\n\nLet us attack! We'll hurl their limbless corpses into the magma they so adore.\n\nYou'll tell Blood Guard Kang what's happened here when we're done, yes? Doubtless I'll need to spend time organizing the repair of the city...", sourceObjective = "Slay Grand Ambassador Flamelash and inform Blood Guard Kang in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27128] = { id = 27128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Gordok", description = "You kill Gordok leader, you new ogre king. If you king, then ogre leaders like Kromcrush and Kreeg that survive pay you big tribute and you stop Gordok invasion. If you do that, then me very happy ogre and we take Dire Maul FOR DA HORDE!!!\n\nGo, little {race}! Kill ugly Gordok ogre king and maybe dis be new Stonemaul Hold! Yar!", sourceObjective = "Kill King Gordok.", progress = "You new Gordok king?", completion = "Little {race} did it! Now Horde more powerful than ever! YAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[27129] = { id = 27129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Warpwood", description = "Just inside the eastern wing of Dire Maul one of the warpwood ancients, Furgus Warpwood, still lives uncorrupted. You must travel there and help him drive out the terrible creatures that have taken it as their own. Taking Dire Maul would be a major step in reclaiming Feralas for our people.\n\nYou can find Dire Maul to the southeast of here.", sourceObjective = "Speak to Furgus Warpwood.", completion = "Have you been in contact with a druid of the talon recently, {class}? I can feel the lingering presence of one.", sourceObjectiveStatus = "unverified-source-field" }
quests[27130] = { id = 27130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Warpwood", description = "Just inside the eastern wing of Dire Maul one of the warpwood ancients, Furgus Warpwood, still lives uncorrupted. You must travel there and help him drive out the terrible creatures that have taken it as their own before they set their sights on Camp Mojache. Perhaps we can even enlist his aid afterward to ensure we maintain our presence in Feralas with enemies on so many sides.", sourceObjective = "Speak to Furgus Warpwood.", completion = "Your face shows signs of desperate conflict. I honor your presence, brave {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27131] = { id = 27131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highborne", description = "Estulan, a powerful and uncorrupt Highborne, has managed to enter the western wing of Dire Maul and has asked for assistance in cleansing it. Regardless of your personal convictions of the Highborne, it is an effort I must support for the good of Feralas. May the wind carry your spirit there with great swiftness.\n\nYou will find Dire Maul to the southeast.", sourceObjective = "Speak to Estulan.", completion = "I sensed your coming all the way from Dreamer's Rest. Your assistance would be most welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[27132] = { id = 27132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highborne", description = "Estulan, a powerful and uncorrupt Highborne, has managed to enter the western wing of Dire Maul and has asked for assistance in cleansing it. Regardless of your personal convictions of his kind, it is an effort I must support for our own good. Please hurry, we need every foothold in Feralas that we can get.\n\nYou will find Dire Maul to the west.", sourceObjective = "Speak to Estulan.", completion = "I sensed your coming all the way from Camp Mojache. Your assistance would be most welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[27133] = { id = 27133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes in the Sky", description = "The most dire, and most organized, threat to us in Feralas are the Gordok ogres in the northern wing of Dire Maul. I requested a druid of the talon to go there and scout it out. If he still lives, speak with him and he will act as your commander to stop the Gordok before they decide to attack.\n\nThat's an order, {class}.", sourceObjective = "Speak to the Druid of the Talon.", completion = "Speak softly, {name}. The Gordok may not be intelligent, but they are still dangerous warriors.", sourceObjectiveStatus = "unverified-source-field" }
quests[27134] = { id = 27134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre in the Field", description = "The most dire, and most organized, threat to us in Feralas are the Gordok ogres in the northern wing of Dire Maul. If we eradicate them and take Dire Maul for the Horde, we will possess a heavily fortified seat of power in this region with numerous artifacts to sweeten the deal. I sent in a small army of Stonemaul Ogres inside earlier - if any have survived, speak with them and finish the job.\n\nThat's an order, {class}.", sourceObjective = "Speak to the Stonemaul Ogre.", completion = "These ogres no pushovers. I need you help me finish Orhan's task, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27135] = { id = 27135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something that Burns", description = "Alright, we need something that's going to make the compound go, \"Boom\"!\n\nI'm all out of gun powder, but I think I know what we can use instead... the heart of my fire elemental!\n\nHere, take my fire totem east to the Blood Trail. Just flip the switch on it near any of the lava pools over there and Magmatooth should be summoned. Bring back his heart and we'll be in business.", sourceObjective = "Obtain the Burning Heart.", progress = "You have the heart yet?", completion = "Uh oh. Sounds like he wasn't very happy about the situation. How was I to know? I'm just an initiate after all.\n\nAnyway, I'll worry about Magmatooth later.", sourceObjectiveStatus = "unverified-source-field" }
quests[27136] = { id = 27136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Energy", description = "It's taking every ounce of our power to keep this realm stable in the absence of the World Pillar.\n\nAs shaman we can tap directly into the energies of the elementals that inhabit Deepholm and use them to heal the damage that the rift is causing.\n\nTake this totem and place it on the ground outside.  Any energized geodes or lodestone elementals destroyed in its proximity will fill it with the energy we require.", sourceObjective = "Destroy 8 Energized Geodes or Lodestone Elementals near the Depleted Totem.", completion = "Thank you, {name}.  We need all the power we can muster to keep Deepholm stable.", sourceObjectiveStatus = "unverified-source-field" }
quests[27139] = { id = 27139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hobart Needs You", description = "Heya, boss, Hobart Grapplehammer's wants to speak with you. He says it's a matter of some urgency.", sourceObjective = "Speak with Hobart Grapplehammer at the Town-In-A-Box on the Lost Isles.", completion = "There you are, my boy. I have something very important for you to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[27140] = { id = 27140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alexi's Gambit", description = "I require your assistance, {class}. Find the undead mage Vectus and the warrior Marduk deep within here. They run the scourge's plagued dragon operation and must be destroyed.\n\nPlace this Gambit in the viewing room where they are located. Hopefully, it will react with their forces and utterly destroy them!\n\nOh, defeating Vectus and Marduk afterward shouldn't be a problem.  Right?", sourceObjective = "Place the Gambit in the Viewing Room and slay Vectus and Marduk.", progress = "Are they defeated?", completion = "You did it!  They are defeated!  And the Gambit... did it work?\n\nVery interesting. You've done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27141] = { id = 27141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploding Through", description = "What a find!\n\nRight here... exactly where my notes predicted it would be.\n\nWith any luck, inside this chamber will lie clues to the location of the legendary Coffer of the Promise.\n\nThat's right, {name}. It's not just a myth. I believe it truly exists.\n\nI'll explain more later. For now, just give me a hand with these explosives.", sourceObjective = "Assist Harrison Jones at the Khartut's Tomb.", completion = "Shake it off, kid.\n\nHappens to me all the time...", sourceObjectiveStatus = "unverified-source-field" }
quests[27142] = { id = 27142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich, Ras Frostwhisper", description = "One of Kel'Thuzad's most trusted students oversees the operations in Scholomance. You must confront the lich, Ras Frostwhisper, in his lair. The door to his chamber is adjacent to the viewing room.\n\nDestroy him, {name}. Leave no trace of his existence so that he may never again bring such horrors into our world.", sourceObjective = "Destroy Ras Frostwhisper.", progress = "You carry the burden of ten thousand restless souls, {name}.", completion = "Ten thousand souls cry out in unison, {name}! You have struck a mortal blow to the Scourge and their masters.", sourceObjectiveStatus = "unverified-source-field" }
quests[27143] = { id = 27143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barov Family Fortune", description = "Within Scholomance lays the Barov family fortune. Alexi and I are the last two Barovs in existence.\n\nHowever, I am the only living Barov, so our family's vast empire belongs to me! Find me the deeds to Caer Darrow, Brill, Tarren Mill, and Southshore and I will repay you generously. The Barov estate will be reborn at long last!", sourceObjective = "Recover The Deed to Caer Darrow, The Deed to Brill, The Deed to Tarren Mill, and The Deed to Southshore.", progress = "Bow your head in my presence, {race}. I am a noble, after all, and you are a copperless peasant.", completion = "Excellent work, {race}. Alexi deserves nothing for his foolishness.", sourceObjectiveStatus = "unverified-source-field" }
quests[27144] = { id = 27144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reckoning", description = "Your performance was admirable, soldier.  You make the Forsaken proud, which is more than I can say for our general, Koltira Deathweaver.\n\nI intend to have a word with that death knight.  He has shamed himself and his cause.", sourceObjective = "Stand by as Lady Sylvanas Windrunner speaks with Koltira Deathweaver.", completion = "I have nothing against the Knights of the Ebon Blade, but Koltira needs to be reminded who he works for now.  His loyalty must lie with the Horde.\n\nOr, more specifically, the Forsaken.\n\nI wouldn't plan on seeing Koltira anytime soon.  Now that I have him... you can rest assured that any bonds he may have had with that Alliance scum will be thoroughly broken.", sourceObjectiveStatus = "unverified-source-field" }
quests[27145] = { id = 27145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plagued Hatchlings...For Now", description = "One of the 'projects' underway here is the plagued dragonflight. Thankfully, they're only hatchlings right now, but if we wait much longer they will become one of the scourge's most powerful weapons and a major threat to all of Azeroth, especially my family's land!\n\nSlay ten of their whelps and be sure to take care of Rattlegore as well. He is in the small space beneath where the whelps are housed and prepares supplements to catalyze their growth. Hurry...before they get any bigger!", sourceObjective = "Kill 10 Plagued Hatchlings and Rattlegore.", progress = "Take out those plagued hatchlings before they grow!", completion = "Well done, {name}!  It'll be a long time before they can grow another clutch of dragons.\n\n...At least, I hope it will!", sourceObjectiveStatus = "unverified-source-field" }
quests[27146] = { id = 27146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doctor Theolen Krastinov, the Butcher", description = "Doctor Theolen Krastinov is responsible for the deaths of thousands. His nickname, The Butcher, is well earned for the atrocities he takes joy in executing. He must be punished, justice must be meted out.\n\nFind him and exact upon him the agony he has inflicted upon countless innocents, including me and my husband. Once he is destroyed, burn our remains. Turn them to ashes, {name}. Release our grieving souls.", sourceObjective = "Destroy Doctor Theolen Krastinov, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff.", progress = "The Butcher must be stopped!", completion = "I can feel my spirit healing, {name}. You have done my husband and I a great service.", sourceObjectiveStatus = "unverified-source-field" }
quests[27147] = { id = 27147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirtonos the Herald", description = "With blood, Kirtonos may be summoned. It is with blood, then, that Kirtonos must be destroyed.\n\nWithin the Chamber of Summoning, you will find a brazier, upon which you shall place a drop of your own blood. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.\n\nShould you succeed, you will earn more than just our gratitude.", sourceObjective = "Destroy Kirtonos.", completion = "With the death of Kirtonos, a chapter in the horrible tale of Scholomance comes to a close. You have my deepest, everlasting gratitude for your bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[27148] = { id = 27148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "School's Out Forever", description = "Darkmaster Gandling serves as headmaster of Scholomance, and is therefore responsible for countless deaths at the hands of his students. For that he must be punished.\n\nHe will not come out easily. Lure him out by slaying his six professors whose rooms connect to the Headmaster's Study. Be wary, for when the last falls he will come, and he will come infuriated with vast magic backing his assault. Don't let him make it out of here alive.", sourceObjective = "Kill Darkmaster Gandling.", progress = "Gandling's school of horrors must be put to a permanent end.", completion = "Without a headmaster, the school will descend into chaos. It will not put forth any more of its vile 'students' into the field. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27149] = { id = 27149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "School of the Damned", description = "Greetings! As you can see, the Western Plaguelands is very nearly free of the last remnants of the scourge. However, their school of necromancy, Scholomance, still sits full of lost young souls training to become scourge sorcerers! Our work here will be for naught if we do not stop this flow of fresh, not to mention very powerful, necromancers.\n\nTravel southeast to Scholomance and find Weldon Barov. He is the last living member of the Barov line that once owned all these lands and is our current contact.", sourceObjective = "Speak to Walden Barov in Scholomance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27150] = { id = 27150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "It's likely that the battle for Andorhal will start up again soon.  In the meantime, you could probably stand to practice your skills as a {class}.\n\nEast of here is a large farm that has been taken over by the Argent Dawn and the Cenarion Circle.  I don't doubt that they'll have some work for you.", sourceObjective = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.It's likely that the battle for Andorhal will start up again soon. In the meantime, you could probably stand to practice your skills as a {class}.\n\nEast of here is a large farm that has been taken over by the Argent Dawn and the Cenarion Circle. I don't doubt that they'll have some work for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27151] = { id = 27151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taelan Fordring's Legacy", description = "Greetings.  How do you do?  My name is Daria.\n\nI am one of the priests in charge of preserving the peace here in Hearthglen.  One of my duties involves maintaining the tower down the trail to the southeast of Hearthglen.  This particular tower is of personal importance to the Highlord.  It's the place where his son was killed.\n\nWith the recent incursion of gnolls, however, maintenance of the tower has grown difficult.  Will you help me rid the trail of some of these gnoll vandals, so I can do my duty?", sourceObjective = "Kill 10 Redpine Looters.", completion = "I must admit, {name}... I have been using my mind vision spell to keep tabs on you.  And I must say... the number of gnolls you found on the trail is truly staggering!", sourceObjectiveStatus = "unverified-source-field" }
quests[27152] = { id = 27152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unusual Behavior... Even For Gnolls", description = "Allow me to concentrate for a moment.\n\n<You feel Daria's mind vision travel elsewhere, then it returns to you.>\n\nFurther down the trail, south of Taelan's Tower, the gnolls have carved out a small meeting area to the east of the main road.  Something is happening there... I'm not certain what.  We should investigate.  I will look for anything out of the ordinary... you just protect yourself.", sourceObjective = "Investigate the gnoll hideout along the trail to Hearthglen in Western Plaguelands.", completion = "Gnolls and necromancy... what a surprise!  And I thought that, here in the Western Plaguelands, we had put these dark days behind us.\n\n<You sense Daria's eyes focusing on something on the ground.>\n\nWait... what is THAT?", sourceObjectiveStatus = "unverified-source-field" }
quests[27153] = { id = 27153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good People of Hearthglen", description = "See those reagents over there?  And these supplies right here?  Those belong to the Argent Crusade.\n\nGnolls are known for thievery, but as far as I know, Hearthglen hasn't had any incursions since the Redpine came.  Very suspicious.\n\nI know a few helpful folks within Hearthglen: Morris Vant, Outfitter Mendelev, Bree Ironstock, and High Cleric Alphus.  All can be trusted, and are well-connected.  Question them, to find out if they know anything about these lost supplies.", sourceObjective = "Speak with Morris Vant, Outfitter Mendelev, Bree Ironstock, and High Cleric Alphus within Hearthglen.", completion = "Did you notice, {name}?  Many names were mentioned, but one name was mentioned far more than the others.\n\nBisp.", sourceObjectiveStatus = "unverified-source-field" }
quests[27154] = { id = 27154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bagging Bisp", description = "Magus Bisp is one of Hearthglen's most preeminent arcanists.  To imagine that he would be interacting with gnolls... and dabbling in necromancy?  Unthinkable.\n\nYou'll find him atop the tower near Hearthglen's main gate.  Hopefully he'll have an explanation for all of this.  If not, well... I wouldn't go to the top of that tower unprepared, {name}.", sourceObjective = "Speak with Magus Bisp atop the mage tower in Hearthglen.", completion = "I suppose that we can take his aggression as an admission of guilt.  You alright, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27155] = { id = 27155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning Yourself In", description = "So... you killed a member of the Argent Crusade, inside of Hearthglen.  Usually that's not smiled upon, even in self-defense.\n\nI recommend you come back to Mardenholde Keep, and turn yourself in to Highlord Fordring.  Hopefully he will hear you out, and will be sympathetic with your situation.  I hope I haven't gotten you in any trouble.", sourceObjective = "Report to Highlord Tirion Fordring at Hearthglen in Western Plaguelands.", completion = "I'm already aware of your actions, {name}.  I welcome you into my town, give you my blessing, and what do you do?\n\nYou slay the traitor that we've been hunting down for weeks.  Well done.  Your heroism is budding much earlier than even I had anticipated.", sourceObjectiveStatus = "unverified-source-field" }
quests[27156] = { id = 27156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's About Time!", description = "Finally!  You're here!  Get to work!\n\nMy men have been sparring with these wooden practice dummies for far too long.  Sure, you can learn how to swing a sword by practicing with a dummy, but real combat requires a real combatant.\n\nHmmm... I had asked for them to send me someone imposing, but I suppose a skinny-armed {race} {class} will have to do.\n\nNow get in there and teach my men how to fight!", sourceObjective = "Challenge and defeat 7 Hearthglen Trainees.", progress = "I'm not paying you to talk to me.  I'm paying you to talk with my soldiers... and then fight with them.", completion = "I'm just looking over my paperwork here, and it says that we were expecting a FEMALE {race} {class}.  You're not, umm...\n\n\n\nNever mind.  It would appear that you are not the person that I originally hired, but you did a good job.  So I'm going to pay you anyhow.", sourceObjectiveStatus = "unverified-source-field" }
quests[27157] = { id = 27157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drudges... <Sigh>", description = "Say, I never caught your name.  {name}?  Pleased to meet you, {name}.\n\nI've got one more problem that needs fixing, and you have a look about you that just screams \"I'm a problem-fixer\".\n\nThere's a small mine on the northern edge of Hearthglen, where we get most of the ore that the town needs.  My drudges who work the mine normally do a decent job.\n\nUnfortunately, it seems that a larger-than-average spider has taken up residence within this cave.  Think you can clear things up for me?", sourceObjective = "Kill Shadril within the mine inside Hearthglen.", progress = "I need to get those drudges back to work.", completion = "Nice work!  In retrospect, I'm glad that other {race} {class} never showed up... you've proven to be all the help I need.", sourceObjectiveStatus = "unverified-source-field" }
quests[27158] = { id = 27158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "Hurry, {name}... there isn't time to waste.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.  With Arthas dead, now is the time for the Alliance to start to retake Lordaeron.\n\nSpeak with the gryphon master, Bibilfaz Featherwhistle, when you are ready, and he will put you on the first flight out there.", sourceObjective = "Report to Thassarian within Andorhal in Western Plaguelands.", completion = "It's about time you arrived, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27159] = { id = 27159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge First... Horde Later", description = "Darkmaster Gandling of the Cult of the Damned leads the Scourge offensive here in Andorhal.  My old counterpart, Koltira, leads the Forsaken forces.  If we're to win Andorhal, we'll have to defeat both, but we will certainly fail if we take on both at once.\n\nI know Koltira well enough to know that he will focus on the Scourge first.  We will do the same.\n\nTake out the weaker, desiccated Scourge to reduce their numbers.  The Forsaken will have to wait to taste our wrath.", sourceObjective = "Slay 15 Desiccated Scourge within Andorhal.", progress = "Thin out the Scourge forces, {name}.  Our victory depends on keeping their numbers down.", completion = "You may not act quickly, but at least you do not fail me.\n\nVery well.  I will have a more important task for you, {name}, when the time is right.", sourceObjectiveStatus = "unverified-source-field" }
quests[27160] = { id = 27160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Machines", description = "Dried-up Scourge... weak.  Abominations... strong.\n\nWe defeat strong abominations... we win war.", sourceObjective = "Destroy 6 Opengut Behemoths in Andorhal.", completion = "Abominations... strong.\n\n{name}... stronger.", sourceObjectiveStatus = "unverified-source-field" }
quests[27161] = { id = 27161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Endless Flow", description = "Araj the Summoner is bolstering the Scourge defenses with simple skeletons... an army of weaklings that will overwhelm you before it overpowers you.  He has assembled animi within Andorhal's northern towers that spew these skeletons out at an alarming rate.  But I've got the solution!\n\n<Lang passes you a handful of grenades.>\n\nTheir function is simple.  Throwing these grenades at a bone animus... or, for that matter, a mob of skeletons... will reduce them to splinters.", sourceObjective = "Use Lang's Hand Grenades to kill 5 Stickbone Berserkers and to destroy a Scourge Bone Animus.", progress = "I know what those devices sound like when they've blown up... and I haven't heard that sound yet.  Get back out there, {name}.", completion = "These grenades are all explosives, nothing more.  I may not be a goblin engineer... but I still understand the value of being able to just explode things every once in a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[27162] = { id = 27162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomancer", description = "The Scholomance is one of the few Scourge holdouts remaining west of the Thondroril.  The headmaster of Scholomance, a cultist by the name of Darkmaster Gandling, has made an appearance on the battlefield.\n\nThis will be his final mistake.\n\nYou will find Gandling in a square near the southern end of town.  I want you to fight and weaken Gandling.  I will join you to help finish him off.", sourceObjective = "Kill Darkmaster Gandling within Andorhal.", progress = "I will not rest until the Lich King's taint is lifted from Andorhal.", completion = "Excellently done, {name}.  And now, with the leader of the Scourge forces eliminated from Andorhal, we bide our time.", sourceObjectiveStatus = "unverified-source-field" }
quests[27163] = { id = 27163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brute Strength", description = "Gandling has brought his lieutenant, Rattlegore, with him.  This clattering horror is far more dangerous than any of the other Scourge you will find upon the battlefield... even the abominations.\n\nYou will find Rattlegore within an old town-hall building, near the center of town.  I recommend caution before fighting him, {name}.  He will not be a pushover.", sourceObjective = "Kill Rattlegore within Andorhal.", completion = "Excellently done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27164] = { id = 27164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj the Summoner", description = "With the animus destroyed, the next logical step is to take out Araj himself, and to take a shard of his phylactery.  You've probably already seen him, lurking at the fountain in the center of town.\n\nTake my grenades with you.  They won't do anything to Araj, but if he decides to summon any of those skeletons, you can use them to blow them away.  Again.", sourceObjective = "Kill Araj the Summoner. You may use Lang's Hand Grenades to destroy Stickbone Berserkers.", progress = "Araj is a formidable opponent.  Be prepared.", completion = "Araj dead... this is good.  That gnome has done his part in winning this war.  As have you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27165] = { id = 27165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory, For Now", description = "The Alliance are victorious, and our forces are still strong.  Military strategy dictates that we attack the Forsaken now, while they are recovering and unaware.  I made a deal, however...\n\nWe will wait.  We attack Koltira and his troops when the time is right.  In the meantime, speak with Ginny Goodwin and take a flight to the Chillwind Camp, to our south.  Commander Ashlam Valorfist will give you your next assignment.\n\nYou will hear from me when you are needed again in Andorhal.", sourceObjective = "Report to Commander Ashlam Valorfist at Chillwind Camp in Western Plaguelands.", completion = "Word arrived shortly before you did, {name}.  With the Scourge ejected from Andorhal, we are one step closer to retaking Lordaeron.", sourceObjectiveStatus = "unverified-source-field" }
quests[27166] = { id = 27166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Fletch!", description = "We must always be prepared for battle, {name}.  Whether that battle is against the Forsaken in Andorhal, against the Scourge in the east, or against some yet-unknown foe is unknown.  What is known, is that we must be ready.\n\nWe are low on arrows.  I can obtain the shafts and heads, but I still need feathers.  The birds that circle to the northwest typically molt this time of year.  Would you mind traveling out into the field and gathering some of these feathers for our camp?", sourceObjective = "Obtain 9 Brownfeather Quills.", progress = "It's good to see you back, {name}.", completion = "I will have my fletchers get to work on these.\n\nI'm glad to see you being so useful right away, {name}.  Perhaps later I will have some more exciting tasks for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27167] = { id = 27167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mighty Hunger", description = "I hail from Westfall, far to the south... as do these men that travel with me.  We are farmers, and nothing more.\n\nI had been told that Lordaeron had been healed, and that it was ready for tilling.  However, this \"Commander\" now tells me that it's too dangerous to proceed.  He says that there's a war going on, and that the plaguelands still aren't healed.\n\nBefore anything else, I need to get some food in my men's stomachs.  Anything will do.  Bear seems to be plentiful.", sourceObjective = "Obtain 5 Sides of Bear Meat from Shaggy Black Bears in Western Plaguelands.", progress = "We've traveled a long way.  Anything you can spare would be appreciated.", completion = "You hunt like a true {class}.  Even if we can't set up our homesteads... at least we can still eat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27168] = { id = 27168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those That Couldn't Let Go", description = "Sorrow Hill, up the road to the northeast, was one of the first places that the Argent Crusaders and Cenarion Circle were able to heal.  The area is now freed of the Scourge.\n\nHowever, there are still many specters of the past that, for some reason, have not passed on into the next world.  They may be mourning, they may have unfinished business... or they may just be lost.\n\nTake my thurible and use it to douse them with holy incense.  One way or another, we will help them move onto the next plane.", sourceObjective = "Use the Holy Thurible on 12 Withdrawn Spirits in Sorrow Hill, and slay them if they react negatively.", completion = "Hopefully most of them passed on peacefully.  I thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27169] = { id = 27169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Blessing", description = "These farmers from the south wish to take these farms, but I can't let them enter the plaguelands unprepared.  Even with the Scourge gone, danger still looms in the form of the Forsaken.  No, we must be ready to fight... and that includes our new visitors.\n\nBefore doing anything else, however, I would recommend that you travel to Uther's Tomb, to the east, and place this tribute before his statue to ask for his blessing.  Speak with the priest that tends to the tomb when you are finished.", sourceObjective = "Enter Uther's Tomb, and use the Chillwind Tribute before his statue.", progress = "Uther was a great hero.  It is my honor to serve him, even after he has passed.", completion = "You and the humans at Chillwind Camp wish to re-take Andorhal?  I wish you luck.", sourceObjectiveStatus = "unverified-source-field" }
quests[27170] = { id = 27170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abandoned Crypt", description = "If you truly intend to move forward in this battle for Andorhal... well, perhaps I can help.\n\nTo the east lies a large crypt.  The bottom level of the crypt was once used for storage of weapons and armor... until the Scourge came.  Now that the undead have left, the weapons are free for the taking.\n\nMost of the weapons are probably rusted and rotten by now, but they will serve better than tunics and pitchforks.", sourceObjective = "Find the Weapons Crate at the bottom of the Crypt in Western Plaguelands.", completion = "Scattered all over the bottom level of the crypt, you find shattered crates that once held weapons and armor.\n\nIt appears that somebody got here before you did.", sourceObjectiveStatus = "unverified-source-field" }
quests[27171] = { id = 27171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambushed!", description = "As you turn around, you see the silhouettes of shambling skeletons on the stairs.\n\nThe undead aren't gone from this crypt.  They were lying in wait!  Furthermore, they appear to be armed with the weapons that you came looking for.\n\nYou'll have to escape from the crypt.  On your way out, you should gather as many pieces of equipment as you can.", sourceObjective = "Obtain 4 Time-Worn Breastplates and 4 Rusted Swords.", progress = "What happened at Uther's Tomb, {name}?", completion = "Attacked by ghosts?  Strange.  I suppose that crypt wasn't fully healed after all.\n\nYou just missed Thurman Grant... you remember, that oaf of a farmer that was here earlier.  He took his men with him and traveled to the nearest farm... against my orders.", sourceObjectiveStatus = "unverified-source-field" }
quests[27172] = { id = 27172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writhing Haunt", description = "The farmers traveled to the Writhing Haunt, an old farm to the northeast, across the river.  Someone needs to keep an eye on them.\n\nBring them those rusty weapons and armor you found.  We can't have them fighting with pitchforks.", sourceObjective = "Bring the Battered Weapons and Armor to Thurman Grant at the Writhing Haunt in Western Plaguelands.", progress = "Did Valorfist send you?  He doesn't know when to let up, does he?", completion = "Well, now that you're here, we'll gladly take that armor off your hands.\n\nYou can keep the weapons, though.  These men wouldn't know which end to hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[27173] = { id = 27173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Is Our Army", description = "I told Commander Valorfist that we could hold our own, and we intend to.  I had a little conversation with the death knight general, Thassarian, on my way over here.  We farmers plan to help in our own way.\n\nWe will take control of this farm, begin to cultivate the land... and then when the battle for Andorhal commences, we will attack the Forsaken from the rear.  They'll never expect it.\n\nFirst, we need to get rid of these Forsaken outriders.  Kill some, then return to me.", sourceObjective = "Kill 10 Forsaken Outriders.", progress = "My men need your help, {name}.", completion = "You fight well, {race}.  My men could stand to learn a few moves from an experienced {class} like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27174] = { id = 27174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "In fact, you might still be able to help train some of my men.  You probably noticed the abomination outside.  We initially tried to fight him, but he didn't fight back.  He seems to want to help out on the farm.\n\nTake a group of four settlers and challenge this abomination to combat.  He seems to be pretty tough, but with one of him and five of you, I think you'll have a chance at beating him.", sourceObjective = "Speak with Gory at the Writhing Haunt and challenge him to combat.", progress = "If we're going to help out in this battle for Andorhal, we need to learn how to fight.", completion = "We can handle things from here.  I thank you for your help, {name}.\n\nI assume that when we next meet, it will be in battle.  Take care of yourself until then.  We'll need all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[27175] = { id = 27175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "These men and women here at Chillwind Camp have noble goals, but their ultimate purpose is war.  I would like to offer you an opportunity to pursue more peaceful goals.\n\nAt the Menders' Stead, beyond war-torn Andorhal to the north, the Argent Crusade has joined forces with the Cenarion Circle.  Together, we work on healing this land from the plague that used to reign here.\n\nAre you interested in joining our cause, {class}?", sourceObjective = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", completion = "Welcome, {class}.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[27176] = { id = 27176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Disc", description = "The etching around the surface of this object indicates that it is of ancient origins, and yet no signs of wear can be detected.\n\nA hole on its edge, full of splintered wood, indicates that it is meant to be put atop a wooden staff of some sort.\n\nBefore showing this to Doctor Jones, you should find the other piece.", sourceObjective = "Obtain the Sultan's Staff, then use the Elaborate Disc to create the Shaft of the Stars.", progress = "Yes, {name}?", completion = "<Doctor Jones puts on his spectacles.>\n\nLet's have a look at this. Shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[27177] = { id = 27177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvage Operation", description = "Between the Horde and the naga, our fleet has been decimated. We can't do anything to bring back the men who gave their lives to the sea, but sink me if I allow all of our supplies to be lost forever.\n\nSwim out to the Obsidian Breakers southwest of Highbank and retrieve our supplies from the wrecks and the ocean floor.", sourceObjective = "Retrieve 8 Recovered Supplies from Waterlogged Crates in the Obsidian Breakers.", progress = "How much were you able to recover?", completion = "Look at all this! You were able to recover more than I thought. We can outfit a whole squad of marines with this stuff.\n\nWe have the gear. If we only had some way to bolster our numbers here in the Highlands...", sourceObjectiveStatus = "unverified-source-field" }
quests[27178] = { id = 27178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga Reinforcements", description = "They've come slithering up from the ocean depths, {name}. The naga. I think their intent is to reinforce the Bastion of Twilight, probably by heading inland via the Verrall river. We can't let that happen!\n\nTeach them that these shores are ours now, and send them scurrying back to the lightless depths.\n\nKill the Blackscale naga worming their way through the Obsidian Breakers!", sourceObjective = "Slay 10 Blackscale Myrmidons or Blackscale Seacallers.", completion = "That'll send 'em packing, {name}! Cho'gall won't be able to count on the naga to back him up in this fight. From here on out, it's just us versus the Twilight's Hammer.\n\n\n\n...And the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27179] = { id = 27179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Work", description = "This unfortunate pygmy was in the wrong place at the wrong time.\n\nAs you ponder his bad luck, you take notice of the symbols covering his shield - far too elaborate for pygmy scrawl.\n\nConfident that Doctor Jones will find such objects of interest, you set out to find more fragments like this one.", sourceObjective = "Collect 10 Ancient Tablet Fragments.", progress = "What'dya have there, friend?", completion = "These tablets are covered with titan writings. There's never-before seen information here, {name}!\n\nMissing pieces to an ancient puzzle...\n\nGood work!", sourceObjectiveStatus = "unverified-source-field" }
quests[27180] = { id = 27180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Dead", description = "A convoy of veteran troopers and Forsaken catapults were ambushed earlier today while attempting to cross Olsen's Farthing, directly south of here. It was a total loss: all troopers were killed and all catapults destroyed.\n\nBloodfang's pack was responsible for the ambush, though likely they have all fled back into the hills, preparing their next cowardly strike. Their day will come, but for now I want you to go to Olsen's Farthing and honor our fallen.\n\nRecover their Forsaken insignias.", sourceObjective = "Recover 6 Forsaken Insignias from Veteran Forsaken Trooper corpses.", progress = "Have you recovered the insignias?", completion = "I will see to it that these insignias are returned to the Undercity at once. The registrar will place their names in our records so that their sacrifice may never be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27181] = { id = 27181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excising the Taint", description = "It looks like a group of the ambushers stayed behind. Make them pay for their insolence! Kill all of the Bloodfang stalkers at Olsen's Farthing. For Sylvanas! For the Horde!", sourceObjective = "Kill 10 Bloodfang Stalkers.", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nYou have avenged the fallen, {name}, but there is more to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[27182] = { id = 27182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Witch Hill", description = "The marsh seems to have a strange effect on humans. Some grow mad simply by living here.\n\nAnyone who has ever settled at Swamplight Manor has gone mad in a spectacular way. The latest owner, one \"Swamp Eye\" Jarl, is already showing signs.\n\nI don't completely understand what's happening there, you'd have my thanks for looking into it.\n\nThe manor is at the eastern edge of the swamp. Trek east across Bluefen and past North Point Tower. The manor is in a haunted patch of land called Witch Hill.", sourceObjective = "Speak with \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Have you come here to spy on me? No?\n\nPerhaps you have an appreciation for fine cuisine, then? Good, you can help!", sourceObjectiveStatus = "unverified-source-field" }
quests[27183] = { id = 27183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsh Frog Legs", description = "I like cooking.  Good swamp cooking.  Fried green frog legs and the like.\n\nAnd I'm all out of legs. The manor is overrun with frogs, though. Giant marsh frogs. Think you could bring me some of those legs? Nothin' to it, really. Just bop 'em on the head and bring me the legs.\n\nThen I'll make a stew and stew it up and suck it down and give you some too.\n\nDo you like stew?", sourceObjective = "Collect 10 Marsh Frog Legs from Giant Marsh Frogs.", progress = "Spice.  We could all use some spice in our life.  You agree?", completion = "Ah, that's the spice!  Now here's some swampy good stew.", sourceObjectiveStatus = "unverified-source-field" }
quests[27184] = { id = 27184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl Needs Eyes", description = "Eye juice is good juice for drinking.  Too bad most critters only have two eyes.\n\nBut spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already.\n\nDarkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?", sourceObjective = "Collect 20 Unpopped Darkmist Eyes from Darkmist spiders.", progress = "Where are those eyes?", completion = "You got the eyes!  You got the eyes!  Tasty, tasty spider eyes!\n\nSome eyes... when you stare at them they stare back. Eat those last.  They keep you company... out in the swamp.\n\nHello, little spider eyes.  Hello!  You taste like chicken.  Gooey, salty chicken!\n\nMmmh.", sourceObjectiveStatus = "unverified-source-field" }
quests[27185] = { id = 27185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting the Competition", description = "Look, I'm not about t' play games with ye. The Scarlet Crusade's Crimson Hammersmith was nothin' worth mentionin' before, but now that they're Balnazzar's Risen, the damned dreadlord has taught him t' make all sorts of powerful demonic weaponry.\n\nIt's simple. Find their blacksmithing plans and kill the Risen Hammersmith when he comes for 'em, so that we can make sure their army doesn't get their hands on demon armaments. They're powerful enough as it is!", sourceObjective = "Kill the Risen Hammersmith.", progress = "Are we back on top of the arms race?", completion = "Nicely done, lad! Without them new weapons, they're just as easy t' kill as they were when they were alive!", sourceObjectiveStatus = "unverified-source-field" }
quests[27186] = { id = 27186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl Needs a Blade", description = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a sword.  I call it a swing blade.\n\nYou help me?  Those fish-men, you know, murlocs or whatever they're called.... There's one they call Razorspine, carries a big sword, lives north of here near the beach. That's the sword I need!\n\nBut don't sleep on this.  What I'm cutting won't keep forever...", sourceObjective = "Obtain Razorspine's Sword.", progress = "You have my blade??", completion = "That's a good blade.  It has a good swing.  It's a good swing blade.  Thank you.  Thank you, thank you, thank you!!!  Now I want to try it....  \n\nLater.  I'll try it later.  But like I was saying... thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[27187] = { id = 27187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do the World a Favor", description = "Hyenas, on their best day, are a nuisance.\n\nThese foul specimens have a particularly nasty disposition, are riddled with all manner of disease, and are simply a blight on the face of dogdom.\n\nDo the world a favor and rid the deserts of Uldum of this mangy menace.", sourceObjective = "Kill 12 Mangy Hyenas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27188] = { id = 27188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Haunting Witch Hill?", description = "I traveled out here to pay Jarl a visit at his new home and it's been a nonstop horror show ever since! There's something seriously wrong here and I can't be the only one who sees it...\n\nHave you seen the ghosts and corpses shambling about Witch Hill? I've a feeling that if anyone knows what happened here, it is them. Seek out these risen husks and risen spirits in the surrounding area, grant them rest through combat, and see what you can learn from them before this evil consumes Jarl!", sourceObjective = "Gather information by defeating 10 Risen Husks or Risen Spirits.", completion = "<Mordant produces a small sheet of paper and a pen, beginning to scribble down notes on your findings.>\n\nFrom your findings, the spirits in this place must amount to everyone who ever lived on this land, not just the previous occupants.\n\nSomething has been corrupting and killing them. Those who follow don't learn the truth until it's too late. We have to put an end to this, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27189] = { id = 27189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Witch's Bane", description = "In my years as an herbalist, I've often observed that nature will provide subtle cures to the most vexing of problems. I've read that hedge mages and witch doctors often use the smoke of an herb known as witchbane to draw evil from its hiding places.\n\nIf true, this would mean witchbane should be growing near the shallow waters of Witch Hill. You should be able to identify it by its broad leaves and reddish central stalk. Bring me any of the herb you can find, {name}. It may be our only hope.", sourceObjective = "Collect 9 sprigs of Witchbane near Witch Hill.", progress = "Were you able to gather any of the herb? We must work quickly, before whatever evil is behind this infestation consolidates its hold on this area.", completion = "<Mordant accepts the bunch of herbs from you.>\n\nThese match the description exactly! I prepared the torch while you were out. All that remains is to fasten the herbs to the end here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27190] = { id = 27190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Witch Hill", description = "The torch is ready. Plant it at the end of the dock and be prepared to face whatever comes forth.\n\nI have no idea what the torch's smoke may reveal... if anything emerges at all. I must say, I have my doubts about this kind of folk magic, but we haven't time for anything else. For your sake and Jarl's, I wish you luck.", sourceObjective = "Plant the Witchbane Torch at the end of the dock and defeat the evil haunting Witch Hill.", progress = "Is it over?", completion = "It worked?\n\n<Mordant clears his throat.>\n\nI mean... it worked! Jarl and I are in your debt, {name}. Now the only remaining problem is my friend's taste in furniture, and I'm afraid that won't be solved as easily.", sourceObjectiveStatus = "unverified-source-field" }
quests[27191] = { id = 27191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungry as an Ogre!", description = "You meet some people out here sometime. Nice people. Met an ogre once. Ogres get hungry just like me.\n\nI'll never forget what he said. He said \"Mud big ogre. Me hungry. Go bash fishy. Bring Mud food. You feed Mud or Mud eat you.\"\n\nSo I got him those fish and he ate 'em up. That's when I started too. The heads are the best part, all soggy-like.\n\nDon't crush those heads now. It makes them sad. Sad heads aren't good eating. Get me happy heads and I'll eat them and be happy too.", sourceObjective = "Collect 8 Mirefin Heads from Mirefin Murlocs.", progress = "Jarl's hungry. Just like that ogre.", completion = "Wonder what it's like to be an ogre. Big people have to eat more.\n\nOgres must be even hungrier than me. That doesn't sound very fun.", sourceObjectiveStatus = "unverified-source-field" }
quests[27192] = { id = 27192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Ezra Grimm", description = "Men as far as Kul Tiras spoke of the legendary Ezra Grimm's premium tobacco. It was a delicacy enjoyed by every single person of importance that visited Stratholme. King Terenas, Uther the Lightbringer, Highlord Fordring...yes, they all enjoyed Grimm's specialty.\n\nSadly, Ezra stayed in his shop when Stratholme was invaded, swearing on his life that the Scourge would never touch his tobacco. Venture forth and see if even one bit remains here...it is worth its weight in gold, I assure you.", sourceObjective = "Recover a box of Ezra Grimm's Premium Tobacco.", progress = "Did you find any?", completion = "Truly, you have uncovered the snuff of legends. It is nearly impossible to place a value on this historical tobacco.\n\nHere, have a few coins.", sourceObjectiveStatus = "unverified-source-field" }
quests[27193] = { id = 27193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek and Destroy", description = "<The Banshee Queen's voice invades your thoughts once more.>\n\nSearch the nearby farmhouses for Alliance stragglers. Keep an eye out for any information that could lead us to Crowley and Bloodfang. Seek and destroy all that would stand in your way, {name}!", sourceObjective = "Search the Farmhouses at Olsen's Farthing.", sourceObjectiveStatus = "unverified-source-field" }
quests[27194] = { id = 27194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cornered and Crushed!", description = "<The Banshee Queen speaks through your mind.>\n\nWe must act quickly, {name}. They mustn't be given the chance to flee. I am dispatching a squadron of my most powerful troopers to the Deep Elem Mine. I'm also sending the Horseman with them to ensure that nothing goes wrong. Meet him at the Deep Elem Mine, east of Olsen's Farthing, and CRUSH those rats.", sourceObjective = "Report to Master Forteski at the Deep Elem Mine in Silverpine Forest.", completion = "I s'pose we're to corner them first then crush, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[27195] = { id = 27195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere to Run", description = "The mistress has put me in charge of this lot. Our primary mission is to get in there, corner the rats, and kill 'em all, including Bloodfang.\n\nYou've done us a solid service in gettin' the information, {name}. Join in the glory and help us drive a sword through their miserable skulls!\n\nLet me know when you're ready and I'll call for the charge.", sourceObjective = "Escort Master Forteski through the Deep Elem Mine.", completion = "WHAT!?\n\n<Sylvanas shrieks.>\n\nCROWLEY!!!!!\n\nBastards. Those were some of our strongest soldiers. I have underestimated Crowley and Bloodfang for the last time. Clearly they are an enemy the likes of which we have never seen - willing to sacrifice their own to set a trap like this... unheard of in Alliance warfare.", sourceObjectiveStatus = "unverified-source-field" }
quests[27196] = { id = 27196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On to Something", description = "This is remarkable work you've done! Especially for someone who hasn't taken my courses.\n\nThese tablets provide new information on several subjects.\n\nThey indicate that these obelisks are part of an enormous ancient mechanism that once kept this whole region masked from the rest of the world.\n\nThey also depict how to recharge the mechanism, which is where your Shaft of the Stars comes in...\n\nGet ready, {name}. We have some history to make!", sourceObjective = "Accompany Harrison Jones to the Chamber of the Stars.", progress = "Alright, now let's see what this staff can show us...", completion = "Would you get a load of this place!", sourceObjectiveStatus = "unverified-source-field" }
quests[27197] = { id = 27197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Resumes!", description = "Word is in from Andorhal, {name}.  The battle has resumed.\n\nIt has become somewhat well-known among the Alliance forces that you're a hero of the first battle of Andorhal.  Thassarian has requested your presence immediately.", sourceObjective = "Report to Thassarian at Andorhal in Western Plaguelands.", completion = "Word has it that you helped those farmers arm themselves.  Well, now they've initiated the attack without my order!  They've forced my hand.\n\nThe battle has resumed.  This time, we fight the Forsaken... and I fight Koltira, my old brother of the Ebon Blade.", sourceObjectiveStatus = "unverified-source-field" }
quests[27198] = { id = 27198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supporting the Troops", description = "I'm no military expert, but this battle looks to be in our favor.  Our defenders are equally matched with their deathguards, but the farmers' militia has taken them by surprise from the rear.  For the Alliance!\n\nStill, we should all do what we can to make sure that we win.  Travel east into Andorhal and slay the Forsaken deathguards that are fighting with our men.  The sooner they die, the quicker we can re-take Andorhal!", sourceObjective = "Slay 15 Andorhal Deathguards.", progress = "For the Alliance!", completion = "You fight well, {name}.  I wish I had your ability... and your bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[27199] = { id = 27199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes to Ashes", description = "To the east, deep within Forsaken-held Andorhal, you will find their commanders.  They do not fight, but call out orders from horseback.\n\nHunt down and slay these commanders, {name}.  The Forsaken won't stand a chance.", sourceObjective = "Slay 3 Deathguard War-Captains.", progress = "You will find them to the east, {name}.  Do not fail me.", completion = "Well done.  With them out of the way, I have no more excuses.\n\nSoon, I must battle Koltira, for honor and for Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27200] = { id = 27200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siren's Song", description = "She's still out there... Ophelia, the Siren of the Highlands! Her terrible song will lure you to the depths. I've vowed to stay behind and avenge my fallen crewmates, {class}. If you want to join me, just say the word.\n\nWe'll lash ourselves to the mast, we will. We'll shut our eyes. We'll stuff our ears with wax. And when her beautiful illusion drops... we'll strike.\n\nAre you in?", sourceObjective = "Slay Ophelia, the Siren of the Highlands.", completion = "She had me under her spell, {name}. I wouldn't have made it out of there alive if it weren't for you. Thank you!\n\nMaybe the rest of the Alliance fleet can finally anchor here in peace...", sourceObjectiveStatus = "unverified-source-field" }
quests[27201] = { id = 27201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'kyr Incursion", description = "The val'kyr were one of the Scourge's primary weapons.  Not only were they skilled in battle, but they could be used to convert corpses into Scourge minions.  To think that Sylvanas is stooping to such levels for the sake of the Forsaken...\n\nWe need to stop the val'kyr before they wipe us out and turn our army against us.  Slay as many as you can find.  And bring some of these minutemen with you.  If they've survived this long, then they must have some battle skill.", sourceObjective = "Kill 9 Lesser Val'kyr within Andorhal.", completion = "For every val'kyr you slay, you save dozens of our men... and prevent the Forsaken forces from growing.\n\nStill, they press on.  We may not win this battle after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27202] = { id = 27202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Against Brother", description = "Our militia has been nearly wiped out.  Only I and these few farmers remain.\n\nThose winged creatures... they took the bodies of our men and... and turned them into walking, undead corpses!  With every one of our men they took, they bolstered their own ranks.\n\nIt pains me to admit it, but you will need to fight them too, along with the deathguards and val'kyr.  As they did in life, they hunt in packs, so take some of my minutemen with you.", sourceObjective = "Kill 20 Forsaken Troopers within Andorhal.", progress = "Try not to remember - while they used to be allies, these men are Forsaken now.", completion = "You fought valiantly, but we're getting nowhere.  Every body that falls just fuels their forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[27203] = { id = 27203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maelstrom", description = "Thank the spirits you're here, {name}.\n\nWe're not sure how much longer we can maintain the rift in the Maelstrom.\n\nOur most powerful members, led by Thrall, are barely preventing the tear.\n\nLast I heard, our only hope was to go through the breach and attempt to stabilize it from the other side.\n\nI will conjure a portal.  Take it and report to Thrall as soon as you can.", sourceObjective = "Go through the Portal to the Maelstrom and speak to Thrall.", completion = "<Thrall's muscles strain as primal energy flows through him.  His eyes shift your way, acknowledging your arrival.>\n\nIt is good to see you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27204] = { id = 27204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aradne", description = "Our last hope of victory lies in defeating the val'kyr.  You've done well up until now... but you're only one <man/woman> and there are literally dozens of them raining destruction on the battlefield.\n\nOne enormous val'kyr sits atop the tower to our south... you can see her from here.  Perhaps if we eliminate her, the remaining val'kyr will dissipate.\n\nThis is our only hope.  Bring some of Grant's men with you.  You'll need their protection for this battle.", sourceObjective = "Slay Aradne atop the tower in western Andorhal.", progress = "How did I let the battle slip between my fingers?", completion = "I watched your victory from below.  Well-fought, but ultimately, it was for naught.\n\nThe val'kyr and the Forsaken press on; soon, they will overtake us.  We have lost Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27205] = { id = 27205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Depravity of the Forsaken", description = "We nearly have this battle won, {name}.  I can taste victory.  The Forsaken never stood a...\n\nWhat the hell is that!?", sourceObjective = "Find out what Thassarian is looking at.", completion = "Val'kyr?  Koltira brought val'kyr to this fight?  Has he gone mad?\n\nNo, this is not Koltira's work.  This was Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27206] = { id = 27206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alas, Andorhal", description = "Head south, to Chillwind Camp.  Tell Commander Ashlam Valorfist everything that happened here.\n\nMe?  I'm going west, into Tirisfal.\n\nMy battle's not over yet.  I've got an appointment with that harpy that calls herself a Banshee Queen... and I'm finding out what she did to Koltira.", sourceObjective = "Report the events of the battle of Andorhal to Commander Ashlam Valorfist.", completion = "Lost?  No... next, they'll be coming for Chillwind, I suppose.  This was a major strategic blow to the Alliance's plans for Lordaeron.\n\nVery well.  I will report the results of this battle to King Wrynn.  I don't expect him to be happy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27207] = { id = 27207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Blows", description = "Is THAT what's behind the storms assailing my city?\n\nLet's push on. That towering windbag can bellow and blow all he likes, but this is the end of him. Tell General Marcus Jonathan what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", sourceObjective = "Slay Prince Sarsarun and inform General Marcus Jonathan in Stormwind City.", sourceObjectiveStatus = "unverified-source-field" }
quests[27208] = { id = 27208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreadlord Balnazzar", description = "With the fall of the Scarlet Crusade, their disguised demon leader, Balnazzar, released the possessed body of Grand Crusader Dathrohan and went on a rampage, killing every remaining crusader here. He then used his necromantic power to raise them all as vile undead slaves.\n\nBalnazzar refers to his new army as the Risen. We cannot let him grow this army - they are extremely powerful and, unlike Arthas' Scourge, Balnazzar will not hold his forces back. Kill him while we still have a chance, {class}.", sourceObjective = "Kill Balnazzar.", completion = "It's good we stopped Balnazzar now. Before long, his army would have overtaken all of Stratholme, giving him a powerful center for his new unholy empire.", sourceObjectiveStatus = "unverified-source-field" }
quests[27209] = { id = 27209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Blows", description = "So. This is what evil lies behind the attacks on fair Thunder Bluff.\n\nLet us move forward. It is time to put an end to this abomination.\n\nTell Hamuul Runetotem what has happened here upon our return; I'll need to oversee the return of my people, repairs, and the like.", sourceObjective = "Slay Prince Sarsarun and inform Hamuul Runetotem in Thunder Bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[27210] = { id = 27210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors Among Us", description = "It's good to meet you, {class}. I've come to Theramore to help eliminate the problem of the deserters. Not only have some of the men abandoned their posts, but some have filtered back into the town.\n\nThese deserter agents are spreading lies and propaganda, hoping to convince others to join their ranks.\n\nThey're at virtually every guard post throughout the town and the docks. Find them, expose them, and discredit them. At this point, anything more risks inspiring more sympathy for them.", sourceObjective = "Confront 5 Deserter Agitators in Theramore.", completion = "Well done, {name}. I think we managed to catch them off guard. Their agents probably thought themselves safe within the city walls.\n\nGiven time, the agitators will return and spread their lies again. We'll use the time you've bought to shut out the deserters further.", sourceObjectiveStatus = "unverified-source-field" }
quests[27211] = { id = 27211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propaganda War", description = "The deserter agents were doing far more than just chatting up the guards. We've found a number of leaflets the deserters somehow managed to smuggle in on a ship in the docks.\n\nThe ship used to transport the leaflets is still in Theramore, at the farthest dock. If you can sneak aboard and capture the rest of their propaganda documents, their agents will lose their most powerful tool. Be careful! The ship is manned by seasoned privateers and the cargo is probably being kept in the captain's quarters.", sourceObjective = "Obtain the Deserter Propaganda from the boat at the end of the Theramore docks.", progress = "Did you manage to find and capture the remaining propaganda leaflets?", completion = "<The SI:7 agent nods in approval.>\n\nExcellent. All that remains is to discredit the deserters so that they'll never gain a foothold in Theramore again, and I have just the plan to do it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27212] = { id = 27212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discrediting the Deserters", description = "I've altered the leaflets you captured from the deserters' mercenary friends at the docks. Now, anyone who reads them will get an entirely different view of the deserters and their aims.\n\nIf we distribute these to enough of the guards, the deserters will be too embarrassed to ever reestablish their presence within our walls.\n\n<Calia hands you a stack of the altered leaflets.>\n\nWhy don't you get started while I plan our next move?", sourceObjective = "Distribute the Altered Leaflets to 6 Theramore Guards.", progress = "I thought I heard laughter coming from the barracks. Did you distribute those leaflets I gave you?", completion = "<Calia chuckles as you describe the guards' reactions to the propaganda.>\n\nJust as I'd hoped! I think it's safe to say any deserter agents who try to infiltrate Theramore will be laughed right out of town!", sourceObjectiveStatus = "unverified-source-field" }
quests[27213] = { id = 27213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Deserters", description = "Now that we've eliminated the deserters from Theramore, it's time to complete this operation. My local contacts have reported that the deserters base their operations in a ship moored on a small island to the southeast of the docks.\n\nArresting their leader, Gavis Greyshield, should cause the others to lose their will to fight. Find him within the ship and convince him to surrender. I wouldn't be surprised if he puts up a bit of a fight for show, but then surrenders when he understands he can't win.", sourceObjective = "Defeat Gavis Greyshield aboard the ship southeast of Theramore.", completion = "Gavis' request isn't as outlandish as it might sound. With the proper handling, Lady Jaina can return the deserters to the fold, but that is her decision, of course.\n\nIt's been a pleasure working with you, {name}. Without your help, I doubt the operation would've gone so smoothly. When I make my report in Stormwind, it will name you as the {class} who ended the deserter threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27214] = { id = 27214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disturbing Development", description = "Reports from our scout patrols have recently taken a disturbing turn. They tell of men wearing red Defias bandanas walking the Dreadmurk Shore north of Theramore's walls.\n\nWreckage in the area suggests they may be survivors of a shipwreck, but our information is limited. Captain Wymor at Sentry Point, a guard tower to the north of the city, is looking for help in following up on the reports.", sourceObjective = "Report to Captain Wymor at Sentry Point.", completion = "<The captain makes no effort to hide that he's assessing your abilities.>\n\nSo you've heard about the recent shipwreck off the coast? Good, I could use some help confirming my suspicions about the survivors. Welcome aboard, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27215] = { id = 27215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Swamplight Manor", description = "There's a fellow the locals know as \"Swamp Eye\" Jarl, who lives alone out in the swamp. Sometime ago he \"took over\" Swamplight Manor after the previous owners disappeared under mysterious circumstances.\n\nI like to send someone to check up on him every once in a while. He kind of reminds me of my grandfather, you know? Some say he's not quite right in the head.\n\nIf you're headed northwest on the road out of Theramore, you'll find Swamplight Manor in the Witch Hill area, before the road turns west.", sourceObjective = "Speak to \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Get off my lawn... unless, that is, you want to help old \"Swamp Eye\" with a little bit of cooking. Whad'ya say?", sourceObjectiveStatus = "unverified-source-field" }
quests[27216] = { id = 27216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Old Lighthouse", description = "The old lighthouse out to the east hasn't worked for some time, but Babs Fizzletorque has gotten it into her head to get it working again.\n\nI don't know how she plans to do it by herself, but she claims that it'll make the movement of ships and goods into the docks smoother, so I can't really object. Drawing duty on the docks is really nothing to complain about when you could be on the front lines, you know?", sourceObjective = "Speak to Babs Fizzletorque at the lighthouse on the island east of Theramore.", completion = "Good. I can use all the help you can offer. My first priority is to get that lamp re-lit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27217] = { id = 27217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thresher Oil", description = "The old log in the lighthouse indicates that the lamp was fueled with oil from the threshers that live along the coast here.\n\n<Babs wrinkles her nose at the mention of such outdated technology.>\n\nI suppose it's a practical, if inelegant solution. The log says that the oil taken from the youngest murk threshers works the best, and those live right underneath the docks of Theramore.\n\nIf you're up for it, would you help resupply the lighthouse with fuel?", sourceObjective = "Collect 4 containers of Thresher Oil from Murk Threshers beneath the Theramore docks.", progress = "Were you able to get any of that thresher oil?", completion = "Well, I have my doubts, but this is the only solution available right now. Once we have it up and running, I'm sure there will be time to look at other ways to fuel the lamp.", sourceObjectiveStatus = "unverified-source-field" }
quests[27218] = { id = 27218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dastardly Denizens of the Deep", description = "You know, it's amazing what you can find in that old lighthouse. After I lit the lamp, I noticed this book in one of the old trunks up there.\n\n<Babs holds up the book and reads the title dramatically.>\n\n\"Dastardly Denizens of the Deep!\"\n\nWhy, I think I might swoon if I ever saw one of these! I'm sure it's good for a laugh or two, but I simply don't have time for reading right now.\n\nYou know who might enjoy it, though... that fishmonger on the docks, \"Dirty\" Michael Crowe. He collects old books.", sourceObjective = "Bring Dastardly Denizens of the Deep to \"Dirty\" Michael Crowe on the Theramore docks.", progress = "What'll it be today? The snook is quite good.", completion = "Well, now, that was thoughtful o' Babs to send that over. I don't know if you've leafed through it or not, but there's a lot of truth to the tales in that book. Sailors didn't just make it all up, you know.", sourceObjectiveStatus = "unverified-source-field" }
quests[27219] = { id = 27219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is it Real?", description = "Oh, I'm sure you and Babs had a good laugh over the outlandish descriptions and sketches in the book, but have you stopped to consider there might be some truth to the legends?\n\nIf you listen closely enough, I bet you can still hear sailors talk about Tethyr, the sea creature the book says lives right here! Of course, if you wanted to know for sure, you could always ask old Nat Pagle.\n\nHe's got a small fishing camp on a little island in Tidefury Cove, which is southwest across Dustwallow Bay.", sourceObjective = "Talk to Nat Pagle at Nat's Landing in Dustwallow Marsh.", completion = "So you want to know about sea monsters? Hmm... well, I'll make you a deal, but it's going to involve a lot of alcohol and some embarrassment on your part.", sourceObjectiveStatus = "unverified-source-field" }
quests[27220] = { id = 27220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nat's Bargain", description = "So you found a copy of Dastardly Denizens of the Deep, did you? Well, I can tell you from experience, it's all true. I've even seen a few of 'em with my own eyes.\n\nBut you want to know about Tethyr.  I said I'd make you a deal, so here's what I want you to do. I'm working on a new line of baits, but I haven't tested this one yet.\n\nJust take this paste -- yeah, it smells a little foul -- smear it on yourself, and swim into the deep part of Tidefury Cove to the southwest. Let me know how it works!", sourceObjective = "Smear Pagle's Fish Paste, Extra Strength on yourself, then swim into Tidefury Cove.", progress = "Remember, the deal is \"don't come back until something bites you.\"", completion = "Not bad at all, but you know, I think I'd get a bath in as soon as possible, if I was you.\n\nNow, about your sea monster...\n\nHelp yourself to a brew or two in the meantime.", sourceObjectiveStatus = "unverified-source-field" }
quests[27221] = { id = 27221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, It's Real", description = "Yes, Tethyr is certainly real, and he lives in the waters off Theramore.\n\nHas a thing for bright lights. He's the reason they shut down the lighthouse in the first place, you know...\n\nAnd if you light it up again, he'll come right back. But no one in their right mind would do that.\n\nSo that must be your plan! It's been good sharing a drink with you, but don't blame ol' Nat if Tethyr REALLY turns you into fish bait. If you're going to do this, make sure you consult Major Mills at the Theramore docks.", sourceObjective = "Speak with Major Mills at the docks in Theramore.", completion = "<You recount your experiences with Nat Pagle, carefully omitting the portion about the 'bait test.'>\n\nWell, it sounds like we've got our work cut out for us. I'll make the preparations.", sourceObjectiveStatus = "unverified-source-field" }
quests[27222] = { id = 27222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Down Tethyr!", description = "Sea monster or no, we're not going to risk the safety of our shipping. I've ordered our best marksmen to prepare for a confrontation with this Tethyr. The artillerymen have augmented the dock's defenses with three mortars.\n\nI'm going to order the lighthouse's lamp illuminated. If Tethyr does attack, it will be your job to operate the mortars and take down the beast before it can kill all of the marksmen. I wouldn't stand in one place too long, though. Using the mortars is likely to draw its attention.", sourceObjective = "Use the mortars to defeat Tethyr.", completion = "Well done, {name}! I'll admit, when I caught my first glimpse of that beast, I had doubts about our ability to defend the docks, but you held together the defenders brilliantly!", sourceObjectiveStatus = "unverified-source-field" }
quests[27223] = { id = 27223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retribution", description = "Where Market Row meets Festival Lane, you will encounter The Unforgiven. If you slay the entirety of Crusaders' Square, you will coax out Timmy the Cruel. Both of these former champions committed heinous acts against innocents here in the name of gaining unholy power.\n\nYou must destroy both of them and rid Stratholme of their foul presence. Take caution, for they were powerful fighters in life, and their new dark powers will only have made them even more deadly.", sourceObjective = "Kill The Unforgiven and Timmy the Cruel.", completion = "You may have this as a suitable reward. I found it nestled in the armor of one of the scourge here.", sourceObjectiveStatus = "unverified-source-field" }
quests[27225] = { id = 27225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Summons from Ander Germaine", description = "Ander Germaine has sent word that he wishes to honor you for your mastery of arms and your dedication to the Alliance. Make your way to Stormwind, leave the Old Town district through the south exit, and speak with him in his Command Center. I do not know what he has planned, but it sounds like he has been impressed with your rapid progress.", sourceObjective = "Speak to Ander Germaine in Stormwind's Command Center.", completion = "It's good to see that you received my message. I have something important I wish to discuss with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27226] = { id = 27226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hair of the Dog", description = "Thank the Warchief that you're here, {name}. I've made a critical error with the sea dogs and need your help to rectify the situation.\n\nYou see, I sent them out against the worgen coming from Fenris Isle stone cold sober. They attacked the beasts and promptly got their butts handed to them. Many of them died, but a few still live, barely clinging on to dear life.\n\nTake this barrel of ale to the Decrepit Fields, east of here, and force it down the throats of fallen sea dogs.", sourceObjective = "Rouse 8 Orc Sea Dogs.", completion = "A-HA! I knew it! Lesson learned, I suppose. We will not fail again. I will be sure to have some ale on hand at the front lines.", sourceObjectiveStatus = "unverified-source-field" }
quests[27227] = { id = 27227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Aurius Rivendare", description = "This Chapel is the last Light amongst so much darkness. Ras Frostwhisper took his own life in the slaughterhouse, carving his face into a macabre smile in front of the Lich King, who raised him into the Lich that now haunts Scholomance.\n\nThe ground where that atrocity occured is now Scourge holy ground, blessed by the Lich King with the very darkest magic. Lord Aurius Rivendare, new ruler of Stratholme, now guards it and continues his master's evil work. Slay him without pause.", sourceObjective = "Kill Lord Aurius Rivendare.", progress = "Don't waste our time. Every second spend chatting away is a second we aren't taking Stratholme back for the Light.", completion = "Stratholme will become a paragon of all that is good in this world. You have my thanks for your part in this mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[27228] = { id = 27228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man Against Abomination", description = "Deep within, you will find Ramstein the Gorger. I cannot bear to tell you the atrocities this monster has commited. Know only this - he deserves to feel the full wrath of countless lost souls, a wrath you will bring upon him.\n\nHave no mercy. Be unwavering in your fury.", sourceObjective = "Slaughter Ramstein the Gorger.", completion = "I respect the power you demonstrated in killing Ramstein. With proper rage backing your actions, I think even the Scourge can know fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[27229] = { id = 27229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SMASH BROODQUEEN", description = "<The following is written in very large print.>\n\nSPIDERS IN NORTH CAVE BAD. POISON OGRES. OGRES GET SICK. BAD!\n\nBIG BIG SPIDER IN CAVE MAKE MORE SPIDERS. MORE SPIDERS BAD!\n\nKILL BIG SPIDER, STOP MORE SPIDERS. KILL BIG SPIDER, GET BIG PRIZE! GOOD!\n\n<A crude drawing accompanies this.>", sourceObjective = "Obtain the Broodqueen Pedipalp.", progress = "Are you here about the sign?\n\nI don't want to talk about it unless you've got proof of a kill.", completion = "By Grom, I'm glad that's over with. If you read that sign you may have some idea how desperate I got after trying to communicate to these lumbering oafs.", sourceObjectiveStatus = "unverified-source-field" }
quests[27230] = { id = 27230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons for War", description = "The Scourge are adept at forging powerful armaments for their soldiers, making it difficult for our men to kill 'em! There are blacksmithing plans near the Baroness Anastari's ziggurat that their chief swordsmith plans to use for an extremely powerful weapon for Lord Aurius.\n\nWe're going to prevent that weapon from being made and stop their regular arms flow with one blow! Go take the plans and kill the Black Guard Swordsmith when he comes to defend 'em, and it'll make our mission much easier.", sourceObjective = "Kill the Black Guard Swordsmith.", progress = "You need to kill their swordsmith! Go!", completion = "Great! Without a steady flow of their weapons, we'll win through attrition!", sourceObjectiveStatus = "unverified-source-field" }
quests[27231] = { id = 27231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcements from Fenris", description = "Those that survived your assault on Fenris managed to drink the blood of the wolf. They turned into ferocious worgen, hell-bent on vengeance. Now they paddle across Lordamere Lake and assault my sea dogs. Many have already been killed. The worgen monsters must be stopped!\n\nMake your way to the Decrepit Fields, east of here, and kill the Hillsbrad worgen that infest the area. Once you've killed them all, make your way to the Horde communication panel, located at the docks. I'll be in touch.", sourceObjective = "Kill 10 Hillsbrad Worgen.", progress = "Report?", completion = "<Hatchet's communication device crackles.>\n\nHatchet here, are they all dead?", sourceObjectiveStatus = "unverified-source-field" }
quests[27232] = { id = 27232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waters Run Red...", description = "<The communication console hums.>\n\nThose worgen you killed were the scouting party. There are hundreds more incoming! Looks like Crowley and Bloodfang made the blood offering to every human in Lordaeron.\n\nGet in one of those Horde cannons and send them all back to their makers. Let the waters of Lordamere Lake run red with their blood!", sourceObjective = "Kill 50 Hillsbrad Worgen with the Horde Cannon.", completion = "Though you killed a large number of the newly turned worgen, many more are sure to appear. Still, their assault will have softened. Well done, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27233] = { id = 27233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Menders' Stead", description = "I can handle training from here.  If you're looking for something else to do, I recommend heading up the road to the northwest.  The Cenarion druids and Argent Crusade have a small camp set up there, at Dalson's old farm.  Maybe they can keep you busy until we need your help again.", sourceObjective = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", completion = "Welcome, {class}.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[27234] = { id = 27234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defias in Dustwallow?", description = "My scouts have reported a shipwreck just off the beach to the northeast. Shipwrecks aren't all that unusual out here, but the reports also indicated the survivors were all wearing red bandanas... the symbol of the Defias!\n\nThe reports indicate their leader resides on a large island just off the coast to the northeast of the tower. Kill him and retrieve any documents you find in his possession.", sourceObjective = "Obtain the Defias Orders from Garn Mathers.", progress = "Were you able to track down their leader?", completion = "<Captain Wymor accepts the orders from you and reads over them.>\n\nWhat in the world could 'precious cargo' refer to? The Defias have done some small time smuggling back in Stormwind, but this seems out of their league. The language of these orders suggests a wealthy or noble patron.", sourceObjectiveStatus = "unverified-source-field" }
quests[27235] = { id = 27235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renn McGill", description = "From the wording of the orders you recovered, it looks like the first priority of the Defias will be to locate and secure whatever cargo they possessed.\n\nSI:7 has had a salvage diver named Renn McGill working out of Theramore for some time. When he heard about the shipwreck, Renn went north to dive near the islands the Defias now occupy.\n\nIf we're to beat the Defias to this cargo, we'll need his help. Look for him in the waters northeast of a small island just north of the island you visited earlier.", sourceObjective = "Bring the Defias Orders to Renn McGill in the waters off the Dreadmurk Shore.", progress = "Well met, {class}. What brings you out here?", completion = "<Renn looks over the orders.>\n\nSo there was valuable cargo on board! We have to locate it before the Defias recover it. These guys are no divers, but we're going to need some of their gear if you're to help me find the cargo.", sourceObjectiveStatus = "unverified-source-field" }
quests[27236] = { id = 27236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secondhand Diving Gear", description = "There's plenty of wreckage strewn across the bottom of the water from here to Alcaz, and the Defias have already got divers out there looking around. With the help of some of their gear, we can get you suited up and ready to join the hunt, but you'll have to do some creative \"borrowing\" first.\n\nSearch this island for a crate of diving gear and something to repair it with. When you've got them, bring them to me and I'll have your gear ready in no time!", sourceObjective = "Bring the Tool Kit and Damaged Diving Gear to Renn McGill in the Dustwallow Marsh.", progress = "Let's see what you managed to \"borrow\" from the Defias.", completion = "Wow, this is in worse shape than I'd thought, and these tools...\n\nWell, I said I'd get this back into working condition for you, so I'd better get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[27237] = { id = 27237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover the Cargo!", description = "Well, I was able to make enough repairs to this gear to let you dive for awhile, anyway. I wouldn't count on it holding out for a long time, though.\n\nThe wreckage of the ship is strewn along the bottom from the east coast of this island out toward Alcaz Island. While that helm holds out, locate pieces of the wreckage on the bottom between this island and Alcaz. Use this salvage kit to search the wreckage for pieces of the cargo. Be careful not to venture too close to Alcaz Island. Those hydra are fierce.", sourceObjective = "Collect 1 Salvaged Strongbox.", progress = "Did your search of the wreckage reveal anything about the Defias cargo?", completion = "<Renn rifles through the contents of the strongboxes you recovered.>\n\nGood work. Now, let's see if our 'precious cargo' is in here....", sourceObjectiveStatus = "unverified-source-field" }
quests[27238] = { id = 27238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina Must Know", description = "You must bring news of our findings to Lady Jaina without delay! If the Defias were transporting a prisoner, there's no telling who it might be or if the person is still alive!\n\nOne thing is for certain, {name}. The Defias wouldn't go to all this trouble for some petty grudge. Their prisoner must have been someone of importance. Lady Jaina would know better than anyone else what these findings mean. You'll find her at the top of the mage tower at Theramore's center.", sourceObjective = "Speak with Lady Jaina Proudmoore in Theramore.", completion = "You and Renn have done excellent work in bringing this information to light and reporting it immediately. Now, we must confirm your findings. The implications are too great if we are wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[27239] = { id = 27239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey Alcaz Island", description = "It looks like Renn's hunch about Alcaz Island was right. We need to survey that island, but it would take a whole brigade of troops to fight our way in there.\n\nTheramore's defenses can't weather such a hit, so I've arranged with Cassa Crimsonwing, the apprentice to Theramore's gryphon master, to allow you to use one of her beasts to survey Alcaz from the air.\n\nAlcaz Island holds the key to the mystery of the Defias' involvement in this kidnapping.", sourceObjective = "Speak to Cassa Crimsonwing and use one of her gryphons to survey Alcaz Island.", completion = "<Lady Jaina listens intently as you report the results of your aerial survey.>\n\nA rune circle, dragonkin? The Defias have allied themselves with HER? The traitor?\n\n<Lady Jaina composes herself and prepares to explain.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27240] = { id = 27240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Treachery", description = "Although Onyxia has been exposed and removed from the court, the Defias who carried out her plan must be punished. Carry word to King Varian Wrynn in Stormwind castle that the Defias are the ones who carried out his kidnapping. I have little doubt that the king will mete out swift and terrible justice to those involved.\n\nI can use my magic to expedite your trip to Stormwind. Just speak to me when you're prepared to go, {name}.", sourceObjective = "Speak with Jaina to travel to Stormwind and meet with King Varian Wrynn.", completion = "So it was the Defias who served as the hands of Onyxia in this plot?\n\n<The king's face grows red with anger and his hands clench into fists.>\n\nYou and Lady Jaina have done Stormwind a great service this day. The traitors will not live long enough to regret their crimes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27241] = { id = 27241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Jaina", description = "I must make plans to destroy the remnants of the Defias. Please convey my thanks to Lady Jaina, back in Theramore. She has ever been a loyal friend and steadfast ally.\n\nGo to the Mage Quarter at the western end of the city and speak with Archmage Malin at the foot of the tower there. He will speed your return to Theramore.", sourceObjective = "Return to Lady Jaina Proudmoore in Theramore.", completion = "I have no doubt that the king meant every word when he told you he plans to destroy the Defias once and for all. He does not make promises lightly, and the enemies of Stormwind should know it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27242] = { id = 27242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Captor", description = "The patch of swamp to the northeast is home to a particularly nasty breed of raptors. We've lost more than one unwary soldier to them, but I think we can turn them against our Grimtotem neighbors.\n\nTake this rope and use it to capture Bloodfen raptors or Bloodfen screechers that you've subdued. I wouldn't try to capture one of the beasts until you've weakened them quite a bit in combat. It's going to be quite a struggle.", sourceObjective = "Use the Sturdy Rope to capture 6 Bloodfen Raptors or Bloodfen Screechers.", progress = "Did you capture those raptors?", completion = "You look a little scratched up, but nothing major. You're certainly in a lot better shape than the Grimtotems will be when our new raptor friends get done with them.", sourceObjectiveStatus = "unverified-source-field" }
quests[27243] = { id = 27243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleash the Raptors", description = "Now that we've got our raptors, our next move is to \"encourage\" them to attack the Grimtotems at Blackhoof Village to the northwest.\n\nI've got a leftover haunch of... well, it doesn't really matter what it is. It'll be your bait. Set it down on the ground in Blackhoof Village near the windmill in the center of the settlement. The raptors should take care of the rest, if their training took.", sourceObjective = "Place the Raptor Bait near the windmill in Blackhoof Village.", completion = "<The sergeant doesn't bother to hide his grin.>\n\nGood. That ought to forestall a raid or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[27244] = { id = 27244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.\n\nAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.", sourceObjective = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.", progress = "You have something for me?", completion = "Good work, {name}.  Our agent, Marg Nighteye, was stationed outside Theramore.  He was charged to spy on the city.  \n\nThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp...", sourceObjectiveStatus = "unverified-source-field" }
quests[27245] = { id = 27245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners of the Grimtotems", description = "We're doing all we can to keep the Grimtotem raiders at bay, but they keep launching assaults on the tower. Even worse, they've managed to discover and capture the patrols the captain sends out to gather information and safeguard the road.\n\nI suspect the captives are being held in Blackhoof Village, to the northwest. Knowing the Grimtotems, the defenders of the village probably carry the keys to the prisoners' cages with them. I don't care what you have to do, {class}, just bring back my men alive.", sourceObjective = "Collect Grimtotem Keys from the Grimtotem Tauren in Blackhoof Village and use them to free 5 Theramore Prisoners.", completion = "The freed captives have already begun returning from Blackhoof Village. The information the captain is receiving from the prisoners will give us an advantage in our next battle against the Grimtotems.\n\nYou have my thanks and that of the men.", sourceObjectiveStatus = "unverified-source-field" }
quests[27246] = { id = 27246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Orc Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is written in orcish... and it looks important.", sourceObjective = "Bring the Spy's Report to Lieutenant Aden in Theramore.", progress = "Do you have a report to make?", completion = "Hm... I can't read orcish very well, but this looks like a report... written by an orc spy!", sourceObjectiveStatus = "unverified-source-field" }
quests[27247] = { id = 27247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Vimes", description = "Captain Vimes should see the orc report you found, {name}.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!\n\nThe captain is in the barracks, on the northeastern side of Theramore Isle.", sourceObjective = "Bring the Spy's Report to Captain Garran Vimes.", progress = "You have something for me?", completion = "A report from an orc spy!  How did you find this?  No matter -- let's see what it says...", sourceObjectiveStatus = "unverified-source-field" }
quests[27248] = { id = 27248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission to Mudsprocket", description = "The Steamwheedle Cartel has recently established a new outpost in the southern part of Dustwallow Marsh. It's called Mudsprocket, if I recall, and it's located on the main road south out of Tabetha's Farm and the Stonemaul Ruins.\n\nThis is an excellent opportunity for us to establish new trade contacts and Lady Jaina wants me to send a representative down there to establish contact. Would you be willing to go?", sourceObjective = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "So Theramore is interested in doing business? Well, that's not an offer I'd turn down. Supplies are pretty scarce here right now, so we need all the business contacts we can get!", sourceObjectiveStatus = "unverified-source-field" }
quests[27249] = { id = 27249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspecting the Ruins", description = "Poor James never recovered from the destruction of the Shady Rest and the murder of his family. The boys and I are doing what we can to find the monsters who did this.\n\nI've sent our best investigator, Inspector Tarem, out to the ruins, but this is too big a job for any one man. If you'd lend Tarem a hand, we'd appreciate it. Light knows, we'd all like to be out there helping.\n\nThe main road will lead you to the inn, but take care. Your journey will take you beyond the protection of my soldiers.", sourceObjective = "Speak to Inspector Tarem at the Shady Rest Inn.", completion = "It's good to see that Captain Vimes is finally assigning others to this investigation.\n\nI've used a reflective powder to dust the area. It will reveal suspicious objects and markings, helping you to focus your efforts. Look over anything the dust illuminates.", sourceObjectiveStatus = "unverified-source-field" }
quests[27250] = { id = 27250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE - BAD COPY", description = "Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?", sourceObjective = "Speak with Vincent Hyal in Menethil Harbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[27251] = { id = 27251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Call Him Smiling Jim", description = "I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place.\n\nLook, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to. He's stationed on the top floor of Foothold Citadel, the large barracks to the east of Lady Jaina's tower.", sourceObjective = "Speak with Captain Garran Vimes on the top floor of Foothold Citadel.", completion = "James Hyal's his real name. He opened an inn at the edge of the Barrens. Wanted to make a nice place for travelers to stop over...\n\nMight be he was thinking too big, but the inn did do well for a while. Then we lost control of the roads in the marsh, and the ogres took over.\n\nJames was too stubborn to give up his dream for safety within our walls, and the Shady Rest Inn was burnt to the ground. We're investigating, but haven't had much luck. If you want to help out, see what you can find in the rubble.", sourceObjectiveStatus = "unverified-source-field" }
quests[27252] = { id = 27252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", sourceObjective = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.", progress = "Have you found evidence from the site of the Shady Rest Inn?", completion = "Hm, I'm no expert with the construction of arms and armor. Their use, yes, but not their making.\n\nThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn.", sourceObjectiveStatus = "unverified-source-field" }
quests[27253] = { id = 27253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspecting the Ruins", description = "If you follow the road south from the village, and then west toward the Barrens, you'll come across the ruins of the Shady Rest Inn.\n\nTheramore has sent an investigator to discover how the inn met its fate. I had a man placed in that inn as a spy and I don't trust in the competence of these humans to uncover what happened.\n\nWhatever you find, don't give a scrap of it to that investigator. We'll handle this ourselves.", sourceObjective = "Investigate the Shady Rest Inn in at the border of the Barrens in Dustwallow Marsh.", completion = "<The inspector regards you with what can only be disdain and distrust.>\n\nLeave this place be, errand boy, or I'll be sure to bring a contingent of guard with me next time to sink the lesson home.", sourceObjectiveStatus = "unverified-source-field" }
quests[27254] = { id = 27254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", sourceObjective = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.", progress = "What's that you have there, {name}? Evidence from the remains of the Shady Rest Inn?", completion = "I grant that humans have strange decorating tastes, but would they use a plain iron shield to adorn their fireplace? Perhaps this shield was placed there by the ones who burned the inn.\n\nA warning? A threat?", sourceObjectiveStatus = "unverified-source-field" }
quests[27255] = { id = 27255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...", sourceObjective = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.", progress = "Something for me, {class}?", completion = "This is good shield. Very strong, heavy, good. But Do'gol don't need it. I make shields, not buy them, {name}.\n\nYou should know that.", sourceObjectiveStatus = "unverified-source-field" }
quests[27256] = { id = 27256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.\n\nI need acid to make it clear. Venom from the darkmist spiders would do good. The spiders have taken over an old mine, the Darkmist Cavern, northwest of the village. Get me some of their sacs and I can clean this up.", sourceObjective = "Collect 5 Acidic Venom Sacs from Darkmist spiders.", progress = "Did you get them sacs from the spiders?", completion = "I don't like spiders that are so big I can't sit on them and squish them.\n\nThanks for getting them, {name}. Now I rip them open and pour them onto the shield...", sourceObjectiveStatus = "unverified-source-field" }
quests[27257] = { id = 27257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...\n\nHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.", sourceObjective = "Speak with Krog in Brackenwall Village.", completion = "Mosarn? Sounds familiar... I can't put my finger on it. Maybe it'll come to me later.\n\nIt probably isn't important. A shield can come from anywhere and not mean anything...", sourceObjectiveStatus = "unverified-source-field" }
quests[27258] = { id = 27258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.\n\nIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.\n\nPerhaps he can tell you more about the shield he crafted.\n\nIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.", sourceObjective = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.", progress = "Hello there, {class}. Something I can help you with?", completion = "Yes, you are certainly correct. This is a shield that I made.\n\nI'm afraid there's not much more I can tell you though, {name}. I craft so many different shields and sets of armor, I can't keep track of them all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27259] = { id = 27259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", sourceObjective = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.", completion = "Hoofprints... It could have been the quilboar, I suppose. Or maybe even the centaur. Their presence in the Barrens is not insignificant, and I would not think it a stretch to commit such an act.\n\nDid I tell you? It wasn't just that the inn was burned down... The owner's woman and pup were killed. Bad business, that.\n\nNonetheless, I will send Kagoro to find where the tracks lead.", sourceObjectiveStatus = "unverified-source-field" }
quests[27260] = { id = 27260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", sourceObjective = "Bring Reethe's Badge to Krog in Brackenwall Village.", progress = "Have you found any leads on what happened at the Shady Rest Inn?", completion = "Hmm... now this is interesting.", sourceObjectiveStatus = "unverified-source-field" }
quests[27261] = { id = 27261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questioning Reethe", description = "It took a long time, but I found Reethe. He hide good for a human.\n\nOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.", sourceObjective = "Go with Ogron to speak with Reethe.", completion = "Hmph. It is good that Reethe will no longer be lurking around the swamp, but it is a shame that humans are built so frail that he could not recover from a little arrow wound.\n\nIt seems that this thread of the mystery has led nowhere, and we must look elsewhere.", sourceObjectiveStatus = "unverified-source-field" }
quests[27262] = { id = 27262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", sourceObjective = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.", completion = "Hoofprints, eh? It is true that there is an extraordinary amount of centaur activity in the lands near the Dustwallow Marsh. In brief excursions into the Barrens, we found their camps and holdings dotting the area.\n\nI'll send out Falgran Hastil, one of our trackers, to see if he can find where the tracks lead.", sourceObjectiveStatus = "unverified-source-field" }
quests[27263] = { id = 27263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", sourceObjective = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.", progress = "Have you found anything of interest at the Shady Rest Inn?", completion = "It's never good news when a guard's badge is brought to me.\n\nSometimes it's a man or woman who's fallen in battle, and I'm left to bring the news to the grieving family. Other times we never find out what happened to them. And other times it's even worse than that.", sourceObjectiveStatus = "unverified-source-field" }
quests[27264] = { id = 27264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenant Paval Reethe", description = "I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.\n\nHe should be able to tell you who this Reethe is with a quick check of his books.", sourceObjective = "Find out more about Reethe from Adjutant Tesoran in Theramore.", completion = "Hello, {name}. You'd like information about a specific member of the Theramore guard? Reethe, was it?\n\nJust give me a moment to find the right book.", sourceObjectiveStatus = "unverified-source-field" }
quests[27265] = { id = 27265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Grayson Shadowbreaker", description = "Lord Grayson Shadowbreaker, one of the foremost paladins in the realm, has asked to speak with you personally. I do not know what he has planned, but it sounds like he has been impressed with your rapid progress.\n\nYou should make your way to Stormwind immediately and meet him inside the city's Cathedral of Light.", sourceObjective = "Speak to Lord Grayson Shadowbreaker in Stormwind's Cathedral of Light.", completion = "It heartens me to see that my message found you, {name}. We have much to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[27266] = { id = 27266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wulf Calls", description = "Wulf Hansreim oversees the training and coordination of hunters in the service of Stormwind. He has asked to speak to you personally. As soon as you are able, travel to Stormwind and exit the Old Town district through the south gate to reach his headquarters.\n\nI have no idea what he has planned, but it sounds like he has been impressed with your rapid progress.", sourceObjective = "Speak to Wulf Hansreim in Stormwind.", completion = "Ah, you've arrived. Make yourself at home, {name}. We have much to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[27267] = { id = 27267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Contact with SI:7", description = "It seems that the leaders of SI:7 have taken an interest in your progress and your service to the Alliance. Osborne the Night Man, a high ranking member of SI:7, has asked to speak with you. Look for him in the southern part of Stormwind's Old Town.\n\nI'm not sure what Osborne wants with you, but it seemed important.", sourceObjective = "Speak to Osborne the Night Man in Stormwind's Old Town.", completion = "I hope my message didn't unnerve you, {name}. I have called you here to recognize your accomplishments.", sourceObjectiveStatus = "unverified-source-field" }
quests[27268] = { id = 27268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Haste to the Cathedral", description = "I have an urgent message for you from Stormwind, {name}. It seems that High Priestess Laurena has asked to speak with you at the Cathedral of Light in Stormwind's Cathedral Square. The messenger did not say what the matter concerned, but that you should travel to Stormwind with all haste.", sourceObjective = "Speak to High Priestess Laurena in Stormwind's Cathedral of the Light.", completion = "It heartens me to see that you received my message and responded so quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[27269] = { id = 27269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of the Moon", description = "I have an urgent message for you from Darnassus. The message is from the High Priestess of Elune, Tyrande Whisperwind, herself! The messenger did not say what the matter concerned, but that you should travel to the Temple of the Moon in Darnassus and meet with the high priestess at once.", sourceObjective = "Speak to Tyrande Whisperwind at the Temple of the Moon in Darnassus.", completion = "Welcome to the Temple of the Moon, {name}. I am glad that you chose to answer my summons so quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[27270] = { id = 27270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with the Farseer", description = "I have an urgent message for you from Stormwind, {name}. It seems Farseer Umbrua has asked to speak with you the next time you're in the city.\n\nThe messenger gave no explanation for the farseer's invitation, but you should travel to Stormwind and find Farseer Umbrua at the Golden Keg in the Dwarven District as soon as you can.", sourceObjective = "Speak with Farseer Umbrua in at the Golden Keg Stormwind's Dwarven District.", completion = "Welcome, {name}. I am glad that you decided to accept my invitation.", sourceObjectiveStatus = "unverified-source-field" }
quests[27271] = { id = 27271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to the Wizard's Sanctum", description = "I just received a message from Stormwind, {name}. One of Stormwind's most renowned mages, Maginor Dumas, has requested that you visit him in the Mage Quarter inside Stormwind. You will be able to find him inside the Wizard's Sanctum atop the large tower in the heart of the Mage Quarter.\n\nI do not know what he has planned, but it sounds like he has been impressed with your rapid progress.", sourceObjective = "Speak with Maginor Dumas at the Wizard's Sanctum inside Stormwind's Mage Quarter.", completion = "Welcome to the Wizard's Sanctum, {name}. I have been watching your progress with interest.", sourceObjectiveStatus = "unverified-source-field" }
quests[27272] = { id = 27272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demisette Sends Word", description = "It seems that the elders in our ranks have taken notice of your progress and dedication, {name}. Demisette Cloyce, one of the oldest and most respected members of our circle, has sent word that she wishes to speak with you. You should not take such an invitation lightly. Most only speak with her in the course of their lessons, but if she has asked to see you personally, it must be an important matter.\n\nHurry back to Stormwind and look for her beneath the Slaughtered Lamb in the Mage Quarter.", sourceObjective = "Speak with Demisette Cloyce at the Slaughtered Lamb in Stormwind's Mage Quarter.", completion = "I see that my message managed to reach you. Good. We have much to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[27273] = { id = 27273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Invitation from Moonglade", description = "You just missed the messenger from Moonglade, {name}. He said little, except that he carried an urgent message from Loganaar, one of the honored trainers of the Cenarion Circle. Head to Moonglade as quickly as you can, {name}. The matter sounds important.\n\nLook for Loganaar in the village of Nighthaven.", sourceObjective = "Speak to Loganaar at Nighthaven in Moonglade.", completion = "I'm glad to see that you have arrived safely in Nighthaven, {name}. I offer you the welcome and the hospitality of the Cenarion Circle.", sourceObjectiveStatus = "unverified-source-field" }
quests[27274] = { id = 27274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chief Surgeon", description = "I have an urgent message for you from Stormwind, {name}. Chief Surgeon Gashweld has asked to meet with you in Stormwind. The message didn't say what the chief surgeon wanted to discuss, but you should make your way to Stormwind as quickly as you can. Look for Chief Surgeon Gashweld in the Dwarven District of the city.", sourceObjective = "Speak to Chief Surgeon Gashweld in Stormwind's Dwarven District.", completion = "I see that you received my message. Excellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[27275] = { id = 27275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together Again", description = "We saw to it that the sentinel was healed and re-equipped. I already sent her back into the field.\n\nHead back up and go to Darkcloud Pinnacle. She'll meet you there.", sourceObjective = "Speak with the Feralas Sentinel at Darkcloud Pinnacle in Thousand Needles.", completion = "Good to see you again, {name}. Let us put the fear of the Goddess into the Grimtotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[27276] = { id = 27276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together Again", description = "We saw to it that the brave was healed and re-equipped. I already sent him back into the field.\n\nHead back up and go to Darkcloud Pinnacle. He'll meet you there.", sourceObjective = "Speak with the Freewind Brave at Darkcloud Pinnacle in Thousand Needles.", completion = "I am honored by your presence, {name}. Let us put the fear of the Earth Mother into the Grimtotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[27277] = { id = 27277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with Ureda", description = "I've received an urgent message from Orgrimmar for you, {name}. The renowned mage, Ureda, wants you to meet with her in Orgrimmar. I'm not sure what this is about, but if I was you, I would travel to the capital as fast as possible and seek out Ureda in the Cleft of Shadow.", sourceObjective = "Speak with Ureda in the Cleft of Shadow.", completion = "Ah, good. It seems my message did find you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27278] = { id = 27278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimshot's Call", description = "A courier from Orgrimmar just delivered a message for you. I'm to tell you that Ormak Grimshot, master of the hunters in Orgrimmar, has asked to meet with you.\n\nTravel quickly to Orgrimmar and present yourself to Ormak in the Valley of Honor.", sourceObjective = "Speak with Ormak Grimshot in the Valley of Honor.", completion = "Good, you're here. Let's get started.", sourceObjectiveStatus = "unverified-source-field" }
quests[27279] = { id = 27279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shattered Hand", description = "A messenger just arrived from Orgrimmar bearing a communication for you. Gordul, the senior rogue trainer in Orgrimmar, has sent for you. You must head to Orgrimmar immediately and meet with him in the Cleft of Shadow.\n\nWhen Gordul summons you, the prudent thing to do is obey. Do not keep him waiting, {name}.", sourceObjective = "Speak with Gordul in Orgrimmar's Cleft of Shadow.", completion = "Now that you are here, we can begin.", sourceObjectiveStatus = "unverified-source-field" }
quests[27280] = { id = 27280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreamseeker Calls", description = "Kardris Dreamseeker, a shaman whose wisdom is legendary in the Horde, has sent word that she wishes to speak with you. The messenger didn't mention what was so urgent, but you should make your way to Orgrimmar as quickly as you can and find Kardris in the Valley of Wisdom. She will be among others who offer training to young shamans.", sourceObjective = "Speak with Kardris Dreamseeker in the Valley of Wisdom.", completion = "I see you are both obedient and talented, {name}. Stay that way, and you will go far in the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27281] = { id = 27281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grezz Ragefist", description = "I just received word that you are needed in Orgrimmar, {name}. Grezz Ragefist, the honored trainer of warriors in the city, has sent for you. It would not be wise to ignore such a summons.\n\nTravel quickly to Orgrimmar and the Valley of Honor where Grezz awaits your arrival.", sourceObjective = "Speak with Grezz Ragefist in the Valley of Honor.", completion = "I see you are both obedient and talented, {name}. Stay that way, and you will go far in the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27282] = { id = 27282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zevrost's Behest", description = "{name}, I have received word that you are needed back in Orgrimmar. Zevrost, one of the senior warlock trainers in the Cleft of Shadow, has something important that he wishes to discuss with you. It seems like the kind of thing that cannot wait.\n\nMake your way back to Orgrimmar and speak with him as soon as you can.", sourceObjective = "Speak with Zevrost in the Cleft of Shadow.", completion = "Ah, you're here at last.", sourceObjectiveStatus = "unverified-source-field" }
quests[27283] = { id = 27283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Journey to Moonglade", description = "As you have heard, Moonglade is the home of the Cenarion Circle, the brotherhood of druids. All who dwell there do so in the peace of Cenarius. It is in that spirit that the trainer Loganaar has extended an invitation to visit him in Moonglade.\n\nYou will find him in the village of Nighthaven.", sourceObjective = "Speak with Loganaar in Nighthaven.", completion = "Welcome to Moonglade, {name}. I have been looking forward to meeting you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27284] = { id = 27284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "I'm sorry I can't be of much help, {name}, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.\n\nTake the shield to him, and see what he can tell you.", sourceObjective = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.", progress = "Something for me to look at?", completion = "Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it's certainly not my work.", sourceObjectiveStatus = "unverified-source-field" }
quests[27285] = { id = 27285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Shield", description = "Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.\n\nThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.", sourceObjective = "Speak with Captain Garran Vimes in Theramore.", completion = "That's not much information to work on, but we'll have to keep it in mind. Hopefully some of the other pieces of this mystery will fall into place, and paint a more helpful picture of what happened.", sourceObjectiveStatus = "unverified-source-field" }
quests[27286] = { id = 27286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daelin's Men", description = "Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.\n\nJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...\n\nListed as missing.", sourceObjective = "Return the information about Reethe to Captain Garran Vimes in Theramore.", completion = "Missing? That would be Tesoran's kind way of saying traitor.\n\nNo doubt he's one of those fools so blindly loyal to Admiral Daelin that he turned traitor.  Isn't that a delicious irony? The deserters accuse us of betraying the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27287] = { id = 27287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deserters", description = "It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.\n\nThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.\n\nThe local lieutenant seems to be Balos Jacken. See if you can get some information out of him.\n\nBe warned, {name}. He may be a tough nut to crack.", sourceObjective = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.", completion = "Did Vimes send you? Couldn't do his dirty work himself, could he...", sourceObjectiveStatus = "unverified-source-field" }
quests[27288] = { id = 27288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deserters", description = "Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?", sourceObjective = "Speak with Captain Garran Vimes in Theramore about Reethe.", completion = "I will send Lieutenant Caldwell to deal with the deserters at Lost Point. In addition, I will instruct him to find Reethe. The marsh is not so big and trackless that he should be unable to find him.", sourceObjectiveStatus = "unverified-source-field" }
quests[27289] = { id = 27289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vimes's Report", description = "You've done some good work, {name}, best I've seen from an amateur.\n\nLady Proudmoore asked that I keep her apprised of this delicate situation, and I haven't spoken to her for some time now.\n\nI was going to deliver my report to her later, but it seems more fitting that you should be the one to speak with her about it. You can probably answer her questions better than I could.", sourceObjective = "Bring Vimes's Report to Lady Jaina Proudmoore in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[27290] = { id = 27290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Forsaken Forward Command", description = "The time has come to destroy Crowley, Bloodfang and every dog at their command. To do this, though, will require cunning and planning the likes of which they would never dare dream!\n\nAs one of my most trusted soldiers, {name}, I need you to go to Forsaken Forward Command, located in Gilneas, and report to Deathstalker Commander Belmont. I have sent Belmont ahead with my plans. He awaits your arrival.\n\nArthura will escort you to Forward Command. Tell me when you are ready and I will send you on your way.", sourceObjective = "Report to Deathstalker Commander Belmont at Forsaken Forward Command in Gilneas.", completion = "Well if it isn't Barksdalenub!\n\nI hope you're ready for battle, because that's all you'll find in this hellhole. We're at the heart of contested territory and these worgen mongrels won't give an inch!", sourceObjectiveStatus = "unverified-source-field" }
quests[27291] = { id = 27291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peace at Last", description = "I wish we had a way of letting James Hyal's wife and son know that we have brought their murderers to justice.\n\n<Captain Vimes produces a small wreath decorated with flowers.>\n\nThere are some who say that their spirits will know, even if we cannot reach them. It's not much, but I'd like you to lay this wreath at the Hyal family monument. It's one of the stones in the graveyard just north of Theramore's gates.", sourceObjective = "Captain Garran Vimes at Foothold Citadel wants you to lay the Wreath at the Hyal Family Monument.", completion = "<Captain Vimes smiles slightly as you relate the events you witnessed at the Hyal family grave.>\n\nIt's good to know that they understand. You didn't tell them about James, did you?\n\nI'll deliver his wife's message to him, but I doubt he'll understand.", sourceObjectiveStatus = "unverified-source-field" }
quests[27292] = { id = 27292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Krog", description = "I hope I've been helpful to you and I'm sorry I can't offer more information. My apprentices and I produce such a large volume of arms and armor that it's almost impossible to recall details about any individual piece.\n\nNot only do we outfit the braves defending tauren lands, but the Grimtotems have a particular fondness for my work. A seasoned warrior knows good work when he sees it.", sourceObjective = "Speak with Krog at Brackenwall Village.", completion = "He actually said that the Grimtotems are his biggest customers? Mosarn gave us more help than he knows. With this much pointing toward the Grimtotems, I think we just found our first suspects.", sourceObjectiveStatus = "unverified-source-field" }
quests[27293] = { id = 27293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem Plot", description = "With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We've seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.\n\nBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems' plans.", sourceObjective = "Collect 4 Grimtotem Notes from Grimtotem Elders and combine them to form the full Grimtotem Battle Plan.", progress = "Were you able to find any trace of the orders?", completion = "<Krog reads over the battle plan.>\n\nThere's no doubt in my mind that the Grimtotems are moving against the humans. What I don't understand is what their intentions are toward us. We knew nothing of these plans and we lost a good man because of it. I don't trust that we're not next on their list.", sourceObjectiveStatus = "unverified-source-field" }
quests[27294] = { id = 27294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More than Coincidence", description = "We've gleaned as much as we can from the ruins of the inn. I'm concerned about where the investigation will lead us from here, but we must know the truth.\n\nBetween the hoofprints and the shield with Mosarn's mark, I'm lead to believe that the Grimtotems may have been involved. They've recently established a settlement in the swamp, Blackhoof Village to the northeast. Travel to Blackhoof Village and search for more arms of Mosarn's manufacture.", sourceObjective = "Collect 7 Blackhoof Armaments from Blackhoof Village.", progress = "What did your search of Blackhoof Village reveal?", completion = "<Krog inspects the weapons and armor you've brought from Blackhoof Village.>\n\nThis is unmistakably the work of Mosarn. Questioning him further may draw too much attention, but we have a bit more freedom in dealing with the Grimtotems.", sourceObjectiveStatus = "unverified-source-field" }
quests[27295] = { id = 27295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Tabetha", description = "The arms you captured in Blackhoof Village have not seen any combat beyond mere training exercises, which means the Grimtotems who destroyed the Shady Rest are still at large.\n\nTo the south, in the heart of the Quagmire, lives the witch Tabetha. Though she is a human, she has dealt honorably with us and trained some of our mages.\n\nAsk her for assistance in tracking down the band of Grimtotem responsible for burning the inn. The Alliance must not be allowed to think we were complicit in the attack.", sourceObjective = "Speak with Tabetha at her farm in the Quagmire.", completion = "<Tabetha smiles slightly.>\n\nKrog wishes me to scry for the Grimtotems, eh? Well, I have no need of magic in this case.\n\nIt seems we have a mutual enemy. The Grimtotems have built an outpost nearby and are a constant thorn in the side of me and my students.", sourceObjectiveStatus = "unverified-source-field" }
quests[27296] = { id = 27296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", sourceObjective = "Use Tabetha's Torch to burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post.", progress = "Have you put that torch to good use?", completion = "The Grimtotems should have no trouble understanding our latest message.\n\nAs for you, your contact at Brackenwall Village will want to know of your success. If I know him, he'll appreciate the taste of vengeance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27297] = { id = 27297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justice Dispensed", description = "I doubt the Grimtotems will give up their campaign to drive humans from the marsh, though I get the impression you probably don't mind that. At least we have dealt with the perpetrators of the crimes at the Shady Rest Inn.\n\nGo tell your leader that his vengeance has been sated.", sourceObjective = "Return to Krog at Brackenwall Village.", completion = "<Krog listens to your report.>\n\nI'm impressed, {name}. I would've thought that the Grimtotem criminals would've been more difficult to locate. The Alliance are truly incompetent.\n\nIn truth, I just sought to answer the death of one of my men, but this situation has been more fortunate than expected. If the Grimtotem choose to retaliate, it will likely be against the Alliance. Perhaps we will soon have the manpower to drive the scum from these shores once and for all.", sourceObjectiveStatus = "unverified-source-field" }
quests[27298] = { id = 27298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out Master Pyreanor", description = "Master Pyreanor, a senior Blood Knight and advisor to the warchief, requires your presence in Orgrimmar. He has taken an interest in your training, {name}, and it is imperative that you speak with him immediately.\n\nThe message I received didn't mention the reason he requested your visit, but you should set out for Orgrimmar right away. Master Pyreanor can be found in the keep in the center of the Valley of Strength.", sourceObjective = "Speak with Master Pyreanor in Orgrimmar's Valley of Strength.", completion = "I've heard much about you, {name}. You have a bright future ahead of you in the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27299] = { id = 27299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torn Ground", description = "It won't be takin' much convincin' to turn us against da Twilight - dat's already our goal. We've already come to battle here though, so we may be needin' ya help before we can turn towards dere fortress.\n\nDa Twilight have already brought Iso'rath up from da ground to the south, I'm sure ya noticed. Its tentacles have been burstin' from da ground all around us. We could use a hand beatin' them down if you be willin'.", sourceObjective = "Kill 3 Tentacles of Iso'rath.", progress = "Did ya have any luck with dose tentacles?", completion = "Tank ya, {class}. A bit of breathin' room helps a lot.", sourceObjectiveStatus = "unverified-source-field" }
quests[27300] = { id = 27300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pushing Back", description = "Da Twilight's Hammer have destroyed a Dragonmaw town to the south and are performin' dey're summonin' rituals from there. Offer dem no respite to continue wit dey're incantations. Bring tha battle to dem!", sourceObjective = "Kill 12 Twilight's Hammer at the Ruins of Drakgor.", completion = "Revenge is bittersweet, but I'm glad we be havin' someone as powerful as you do see dis done.", sourceObjectiveStatus = "unverified-source-field" }
quests[27301] = { id = 27301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbroken", description = "We are preparing a ritual that may be of use in destroying Iso'rath, the old god bred abomination that the Twilight's Hammer have brought up from the depths. We are delayed though, for one of our strongest was captured during an assault on their encampment.\n\nEarthcaller Yevaa is within the ruins to the south. She is not dead. I am sure of it. Please, rescue her. If any of us is deserving of your aid, it is her.", sourceObjective = "Find Earthcaller Yevaa within the Ruins of Drakgor.", completion = "Thank the elements that you've come. Did my brothers send you?", sourceObjectiveStatus = "unverified-source-field" }
quests[27302] = { id = 27302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Simple Solutions", description = "I'm new to this gig. Very new. But ya know what? That gives me perspective!\n\nThese shaman buddies of mine have come upon somethin' great, but they're too single minded! They lean on the elements and they forget to make use of the common materials all around them.\n\nIn the ruins to the south, I saw those Twilight goons tote in barrels of flammable oil! They used it when they razed the town. I say we use it when we raze them.", sourceObjective = "Gather 10 barrels of Pyreburn Oil.", progress = "I wonder what happens when you douse an elemental with that stuff. Jumbo-super-bonfire-elemental? I'm thinkin' so. We'll have to try.", completion = "Now that's what I'm talkin' about! Can you think of all the uses for this stuff? I definitely can't. But I can think of a lot, and I'm liking the possibilities.", sourceObjectiveStatus = "unverified-source-field" }
quests[27303] = { id = 27303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mercy for the Bound", description = "It goes without saying that I had no desire to stay here, but there were materials we needed for the ritual... I delayed to secure them, and that is what lead to my capture.\n\nI will return to the circle, but I would be indebted to you if you would finish what I could not. We need hearts from the bound fire elementals that the Twilight's Hammer enslave in the western portion of the encampment.\n\nThe elementals are without hope, but in this sacrifice they can extract their revenge.\n\nFind me at camp.", sourceObjective = "Gather 5 Fleshburner Hearts.", progress = "Did you recover the hearts?", completion = "Thank you, {name}. You are quite capable. I'm extremely grateful that you've chosen to aid us.", sourceObjectiveStatus = "unverified-source-field" }
quests[27304] = { id = 27304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow the Sun", description = "Sunwalker Atohmo sends word from Orgrimmar -- he wishes to speak with you when you're in the city. I needn't remind you that Atohmo is an honored member of our order and his requests should not be ignored.\n\nNext time you are in Orgrimmar, travel to the Valley of Wisdom and speak with him.", sourceObjective = "Speak with Sunwalker Atohmo in Orgrimmar's Valley of Wisdom.", completion = "I've heard much of your contributions to the Horde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27305] = { id = 27305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Love and Family", description = "Inside the Scarlet Bastion is a painting of great personal value to Highlord Tirion Fordring. Search for a painting of our twin moons. Chip away at the paint until you uncover the master work, 'Of Love and Family.'\n\nMay the Light guide your actions, and please handle the painting with the utmost care.", sourceObjective = "Find 'Of Love and Family.'", progress = "The painting, {name}. Do you have the painting?", completion = "Master Fordring will be glad beyond measure to see this painting again.", sourceObjectiveStatus = "unverified-source-field" }
quests[27306] = { id = 27306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talk to Ogron", description = "I know this human, Paval Reethe. Pathetic, even for his kind. He deserted his fellow soldiers and is now hiding out in the woods.\n\nI sent Ogron out to track him down. Some of the others suspect he's been stealing from our supplies. I think I saw Ogron heading off to the southeast.", sourceObjective = "Find Ogron to the southeast of Brackenwall Village.", completion = "Ogron? Yeah, that me.\n\nShh. Keep voice down. Crocs hear you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27310] = { id = 27310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Weapons For You!", description = "Alright, these cowards want to fight? Let's see how well they do without any weapons.\n\nI'm sure you must have a torch, or something. Burn their weapon racks.\n\nBurn them all!", sourceObjective = "Burn 8 Grimtotem Weapon Racks.", progress = "We'll need to destroy more of their weapon racks if we're going to put a dent in their ability to fight.", completion = "Let's see them wage their war now!", sourceObjectiveStatus = "unverified-source-field" }
quests[27311] = { id = 27311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Weapons For You!", description = "The Grimtotem want to fight? Let us see how well they do without their weapons.\n\nI'm sure you must have something that burns. Set their weapon racks ablaze, my {class} friend.\n\nLet nature take its course.", sourceObjective = "Burn 8 Grimtotem Weapon Racks.", completion = "Let us see how well they fight without their weapons.", sourceObjectiveStatus = "unverified-source-field" }
quests[27312] = { id = 27312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkcloud Grimtotem", description = "There's no way around it. If you want to win a battle, you have to spill some blood. In this case... a lot of it.\n\nYou know what we have to do.", sourceObjective = "Slay 20 Grimtotem Tauren at Darkcloud Pinnacle.", completion = "That put a dent in their numbers! Can't say that they didn't deserve it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27313] = { id = 27313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkcloud Grimtotem", description = "There is no alternative: if you intend to win a battle, you must spill the enemy's blood. In this case, unfortunately, a lot of it.\n\nYou know what we have to do.", sourceObjective = "Slay 20 Grimtotem Tauren at Darkcloud Pinnacle.", completion = "While the Earth Mother does not condone such violence, we had no choice. The Grimtotem have ignored Her teachings for too long and are reaping what they have sown.", sourceObjectiveStatus = "unverified-source-field" }
quests[27314] = { id = 27314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Isha Gloomaxe", description = "Sentinel training 101: take out their leaders and your enemy's forces will soon fall apart. We're going to do just that, {class}.\n\nIsha Gloomaxe is the closest of the Grimtotem chiefs. Let's see if we can't take her measure.", sourceObjective = "Slay Isha Gloomaxe.", progress = "Isha Gloomaxe must meet her end, {name}!", completion = "She was tougher than I thought. We worked well together, but we're going to have to make sure not to underestimate the other Grimtotem chiefs.", sourceObjectiveStatus = "unverified-source-field" }
quests[27315] = { id = 27315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Isha Gloomaxe", description = "Basic brave philosophy dictates that if you kill the leaders of your enemy's forces, they will soon fall into disarray. We are going to do just that, {class}.\n\nIsha Gloomaxe is the closest of the Grimtotem chiefs. We will test her and her axe, and she will be found wanting.", sourceObjective = "Slay Isha Gloomaxe.", completion = "She was more formidable than her reputation suggested. Although we worked well together, we must make certain not to underestimate the other Grimtotem chiefs.", sourceObjectiveStatus = "unverified-source-field" }
quests[27316] = { id = 27316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rattle of Bones", description = "A tauren rattle lays here, exuding supernatural power. Its keepers slain, the artifact is undefended.\n\nPerhaps the sentinel will have some insight into its significance?", sourceObjective = "Give the Rattle of Bones to the Feralas Sentinel at Darkcloud Pinnacle in Thousand Needles.", progress = "That's the fabled Rattle of Bones, {name}!", completion = "It's true then! What is it doing here, though? And if it's here, that must mean that the writ and the drums are also nearby!\n\nMaybe there's some link between it and the wind serpent that just appeared? I think that I've an idea what that creature is as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27317] = { id = 27317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rattle of Bones", description = "A tauren rattle lays here, exuding supernatural power. Its keepers slain, the artifact is undefended.\n\nSurely the brave will have some insight into its significance?", sourceObjective = "Give the Rattle of Bones to the Freewind Brave at Darkcloud Pinnacle in Thousand Needles.", progress = "The fabled Rattle of Bones, {name}!", completion = "It is true then! What is it doing here, though? And if it is here, that must mean that the writ and the drums are also nearby!\n\nPerhaps there is some link between it and the wind serpent that just appeared? I think that I have an idea what that creature is as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[27318] = { id = 27318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Elder Stormhoof", description = "Elder Stormhoof is a shaman of immense power. Supposedly, he is a direct disciple of Magatha Grimtotem, the Elder Crone, leader of the Grimtotem clan.\n\nWe know that he's here and that he's been training their geomancers. We have to kill him, {class}.", sourceObjective = "Slay Elder Stormhoof.", completion = "That's two of them. Two more to go.\n\nI wonder what he meant about being \"chosen\"?", sourceObjectiveStatus = "unverified-source-field" }
quests[27319] = { id = 27319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Elder Stormhoof", description = "Elder Stormhoof is a shaman chief of immense power. He was taught by Magatha Grimtotem, the Elder Crone, leader of the Grimtotem clan.\n\nWe know that he is here and that he has been training their geomancers. We have to kill him, {class}.", sourceObjective = "Slay Elder Stormhoof.", progress = "We must kill Elder Stormhoof before we deal with the rest of the Grimtotem chiefs.", completion = "That was not pleasant. I wonder what he meant by calling you, \"the Chosen\"?", sourceObjectiveStatus = "unverified-source-field" }
quests[27320] = { id = 27320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writ of History", description = "In shu'halo myth, the Rattle of Bones is connected with the Writ of History and the Drums of War. They are supposed to be powerful tauren artifacts.\n\nWe must keep our eyes peeled if we're to find the other two. The writ will most likely look like some kind of pictographic scroll if the stories are to be believed.", sourceObjective = "Collect the Writ of History.", progress = "We'll need the actual writ, not just any tauren scroll hanging.", completion = "I'm fairly certain that's it. This is very intriguing, {name}. What are they doing here? Are they being used as a weapon?\n\nThe wind serpent flew northwest to that next bluff. Maybe that's where the drums are?", sourceObjectiveStatus = "unverified-source-field" }
quests[27321] = { id = 27321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writ of History", description = "The Rattle of Bones is a part of shu'halo ancient myth. It is always connected with the Writ of History and the Drums of War. They are supposed to be powerful tauren artifacts; gifts from the Earth Mother if the tales are to be believed. I cannot imagine Her being connected with the drums, though.\n\nWe must be vigilant if we are to find the other two. The writ will look like a pictographic scroll if memory serves.", sourceObjective = "Collect the Writ of History.", progress = "We will need the actual writ, and not just any scroll hanging.", completion = "This is very exciting and also worrisome, {name}. What are these artifacts doing here? Are they being used as a weapons against us by the Grimtotem?\n\nThe wind serpent flew northwest to that next bluff. Maybe that's where the drums are?", sourceObjectiveStatus = "unverified-source-field" }
quests[27322] = { id = 27322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korok the Colossus", description = "The monstrosity has fallen, granting a brief reprieve to the Forsaken soldiers on the front lines.\n\nTake Korok's second head and return it to Forward Commander Onslaught at Forsaken Forward Command.", sourceObjective = "Take Korok's Second Head to Forward Commander Onslaught at Forsaken Forward Command in the Ruins of Gilneas.", progress = "Korok is dead?", completion = "That towering behemoth has killed hundreds of Forsaken soldiers. You've done a great thing, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27323] = { id = 27323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Grundig Darkcloud", description = "One of the infamous Grimtotem leaders of the Stonetalon Mountains has returned home.\n\nWe should take this opportunity to make sure that he doesn't go anywhere else.", sourceObjective = "Slay Grundig Darkcloud.", completion = "<The sentinel gives you an appraising look.>\n\nWhat is it with you? Why do they all seem spooked by you being here?", sourceObjectiveStatus = "unverified-source-field" }
quests[27324] = { id = 27324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: Grundig Darkcloud", description = "One of the most accomplished Grimtotem leaders of the Stonetalon Mountains has returned home.\n\nWe must make the most of this chance and put an end to his campaign of terror once and for all.", sourceObjective = "Slay Grundig Darkcloud.", completion = "<The brave gives you an appraising look.>\n\nThere is something special about you, {name}. That much is certain.", sourceObjectiveStatus = "unverified-source-field" }
quests[27325] = { id = 27325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drums of War", description = "Whatever the Grimtotem are doing with these Drums of War, we don't want them to have them.\n\nDon't worry, {name}, we'll figure it all out. But first, we need to gather all of the pieces of the puzzle.", sourceObjective = "Collect the Drums of War.", progress = "The tauren love their drums. I can only imagine the Drums of War will be somehow different from the others.", completion = "Surely that was the voice of the Elder Crone!\n\nWe must be very careful, {name}. Great danger lies ahead if Magatha Grimtotem has taken notice of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27326] = { id = 27326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drums of War", description = "Whatever it is that the Grimtotem are doing with the Drums of War, we do not want them to keep them.\n\nDo not worry, {name}, we will figure out what is going on here. But first, we need to gather all of the artifacts.", sourceObjective = "Collect the Drums of War.", progress = "War is not an activity to engage in for those who are faithful to the Earth Mother's teachings.", completion = "Surely that was the voice of the Elder Crone!\n\nWe must be very careful, {name}. Great danger lies ahead if Magatha Grimtotem has taken notice of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27327] = { id = 27327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: The Chief of Chiefs", description = "And now the time has come to take out the leader of all of the Darkcloud Pinnacle Grimtotem: Arnak Grimtotem.\n\nIt is said that he's the disgraced nephew of Magatha Grimtotem, the Elder Crone and matriarch of the Grimtotem clan. Supposedly, his indiscretions have left him in a state of disfavor with her.\n\nBut none of that matters right now. All that matters is that we kill him. For good this time.", sourceObjective = "Slay Arnak Grimtotem.", progress = "We have to kill Arnak, {name}, if we are to win the battle for the tauren of Freewind Post.", completion = "For some reason they all think that you've been sent by Magatha Grimtotem. I know it must have something to do with that wind serpent that's been hanging around.\n\nDoesn't matter. Their leader is dead. It's only a matter of time before the tauren of Freewind Post regain their home.\n\nIf I were them, I'd push back a little to teach the Grimtotem a lesson, but they probably won't. They're tauren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27328] = { id = 27328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimtotem Chiefs: The Chief of Chiefs", description = "The time has come to deal with the leader of the Darkcloud Pinnacle Grimtotem: Arnak Grimtotem.\n\nHe is the disgraced nephew of Magatha Grimtotem, the Elder Crone and matriarch of the Grimtotem clan. His indiscretions have left him in a state of disfavor with her.\n\nNone of that matters now. All that matters is that we deal with him. Once and for all.", sourceObjective = "Slay Arnak Grimtotem.", progress = "Arnak must fall, {name}, if we are to win the battle against the Grimtotem.", completion = "They all believed that you have been sent by Magatha Grimtotem. There is no arguing that her pet, Arikara, has been lurking about.\n\n<The brave gives you a long look.>\n\nIt does not matter. Arnak is dead. It is only a matter of time before we take back Freewind Post.\n\nPerhaps now we will be able to establish a lasting peace with the Grimtotem?", sourceObjectiveStatus = "unverified-source-field" }
quests[27329] = { id = 27329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invoking the Serpent", description = "I am familiar with these artifacts. I believe that they were brought here by Magatha Grimtotem herself. But she's not amongst the Grimtotem on Darkcloud Pinnacle. She disappeared right after she arrived, and no one knows where she is now.\n\nMaybe we can find out.\n\nTake the rattle, the writ, and the drum out to Arikara's Needle. If my guess is correct, the wind serpent will appear again. You'll have to defeat it to gain knowledge of where Magatha is hiding.", sourceObjective = "Defeat Arikara.", progress = "Only by subduing Arikara will you discover where Magatha Grimtotem is hiding.", completion = "So, she's been taken prisoner by the Twilight's Hammer. I can't say that I feel sorry for her, but she might prove even more dangerous in their hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27330] = { id = 27330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invoking the Serpent", description = "I am familiar with these artifacts. I believe that they were brought here by Magatha Grimtotem herself. But she's not amongst the Grimtotem on Darkcloud Pinnacle. She disappeared right after she arrived, and no one knows where she is now.\n\nMaybe we can find out.\n\nTake the rattle, the writ, and the drum out to Arikara's Needle. If my guess is correct, the wind serpent will appear again. You'll have to defeat it to gain knowledge of where Magatha is hiding.", sourceObjective = "Defeat Arikara.", progress = "Only by subduing Arikara will you discover where Magatha Grimtotem is hiding.", completion = "So, she's been taken prisoner by the Twilight's Hammer. I can't say that I feel sorry for her, but she might prove even more dangerous in their hands.", sourceObjectiveStatus = "unverified-source-field" }
quests[27331] = { id = 27331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seer's Call", description = "I just received word that you are needed in Orgrimmar, {name}. Seer Liwatha has asked for you to return to the city as quickly as you are able. Her message didn't include any other information, and the matter seemed urgent.\n\nLook for Seer Liwatha in Orgrimmar's Valley of Wisdom.", sourceObjective = "Speak with Seer Liwatha in Orgrimmar's Valley of Wisdom.", sourceObjectiveStatus = "unverified-source-field" }
quests[27332] = { id = 27332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Shadow-Walker", description = "Shadow-Walker Zuru requires your presence in Orgrimmar right away, {name}. Do not keep him waiting, as it sounds like a matter of some importance.\n\nYou can find the shadow-walker in the Valley of Spirits inside Orgrimmar.", sourceObjective = "Speak with Shadow-Walker Zuru in Orgrimmar's Valley of Spirits.", completion = "The spirits knew that you would answer my call, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27333] = { id = 27333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Ground", description = "I don't know how much longer we can hold out for, {name}. Crowley and Bloodfang's worgen know every hidey hole and safe spot in Gilneas. One minute they're standing in front of you and the next minute they're gone! We're gonna lose this war to attacks of opportunity, even though we have a superior military presence.\n\nBut momma didn't raise no quitter! Forsaken until the end, my friend.\n\nHead west into the headlands and help our soldiers on the front line. Kill the attacking worgen rebels!", sourceObjective = "Kill 12 Worgen Rebels.", completion = "If I could still breathe I'd let out a sigh of relief.\n\nDon't get too comfortable, though, {name}, your mission here has just begun.", sourceObjectiveStatus = "unverified-source-field" }
quests[27334] = { id = 27334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Cleric Cecille", description = "I just received a message from Dark Cleric Cecille in Orgrimmar. She requests that you join her in the audience chamber in Grommash Hold, where you can find her with the delegation from Undercity. The cleric didn't mention the purpose of your visit, but it is clearly important. Make haste, {name}.", sourceObjective = "Speak with Dark Cleric Cecille in Grommash Hold inside Orgrimmar's Valley of Strength.", completion = "There you are, {name}. I was beginning to think my message hadn't found you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27335] = { id = 27335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from Tyelis, a priest trainer and emissary from Silvermoon.\n\nHe asks you to meet him inside Grommash Hold in Orgrimmar. You should make your way there immediately, {name}. It sounds important.", sourceObjective = "Speak with Tyelis at Grommash Hold in Orgrimmar's Valley of Strength.", completion = "Welcome, {name}. I'm glad that you accepted my invitation. We have much to discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[27336] = { id = 27336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimtotem Weapon", description = "During the last Grimtotem attack, I was wounded, but not before I managed to capture a curious totem our enemies were using against us.\n\nIt seemed to be emitting raw bolts of energy during the battle, but in all my experiments, I haven't managed to figure out how it works. I'll loan the totem to you if you agree to help me test it.\n\nThe watery areas surrounding the farm are home to pesky mottled drywallow crocolisks and drywallow daggermaws. Try fighting the crocolisks near the totem.", sourceObjective = "Use the Captured Totem to set it on the ground, and kill 10 Mottled Drywallow Crocolisks or Drywallow Daggermaws near it to test its effects.", progress = "Have you had any luck testing the totem?", completion = "<The apprentice listens as you describe your experiment.>\n\nA haze and some lightning? That's it? There's got to be more to the totem than just that! The Grimtotems aren't likely to bring something like this to the battlefield unless it has some kind of utility.", sourceObjectiveStatus = "unverified-source-field" }
quests[27337] = { id = 27337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fitting Weapon", description = "From your earliest days, {name}, your trainers identified you as a natural talent. Your rapid progress and dedication have made you an example.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nLegend has it that the cursed Shadowfang Keep in Silverpine Forest is home to a variety of materials that you will need. Travel there and find the lost Silverlaine family sword, a supply of moonsteel ingots, and sinew from ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Silverlaine Family Sword from Baron Silverlaine, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ander told me to expect you. It's quite an honor to be crafting a weapon for you, {name}. With these materials, it will be a fine blade indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27338] = { id = 27338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Boys on the Shore", description = "The situation here in the Highlands changes by the minute. Our objective is to storm the Bastion of Twilight, but I can't even secure a landing zone on the shore without the blasted Horde creating trouble.\n\nWhile I scrape together the remains of the fleet, I need men on the shore securing the beach head.\n\nReport to Lieutenant Emry on the shore and help his marines to beat back the Horde!", sourceObjective = "Report to Lieutenant Emry at the Twilight Shores in the Twilight Highlands.", completion = "Keep your head down 'fore you lose it, {class}!\n\nThis is MY beach.\n\nThe Horde WANTS my beach.\n\nThey will NOT have my beach.\n\nIs the beach situation clear?", sourceObjectiveStatus = "unverified-source-field" }
quests[27339] = { id = 27339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Reagent Thief", description = "If there's one thing you can count on Apprentice Morlann to do, it's whine about reagents.\n\nNormally, I just ignore him, and it never works. This time, I'm going to try something different.\n\nMaybe if I replace the missing reagents before he notices, he'll leave me alone. The most common reagent we both use is marsh venom, which comes from the darkfang creepers and noxious shredders in the marsh north of the farm. If you bring me the venom, I'll replace it before Morlann notices it's gone.", sourceObjective = "Collect 6 vials of Marsh Venom from Darkfang Creepers or Noxious Shredders.", progress = "Did you get that venom? Morlann's going to discover that it's gone any moment now...", completion = "<Apprentice Garion inspects the venom.>\n\nThis is absolutely perfect! He'll never know the difference.", sourceObjectiveStatus = "unverified-source-field" }
quests[27340] = { id = 27340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direhorn Raiders", description = "The Grimtotems up at Direhorn Post, just to the north, are getting bolder by the day. At night, you can often hear them chanting about their deeds in battle against people who've tried to settle here.\n\nThey're determined to drive us from Tabetha's farm even though she's trained generations of apprentices here. We've defended the farm as best we can, but Apprentice Garion was wounded in the last attack.\n\nGo to Direhorn Post and kill any Grimtotem you can find! The attacks must stop.", sourceObjective = "Kill 12 Grimtotem in Direhorn Post.", completion = "<Apprentice Morlann nods.>\n\nGood. Can't say I'll miss the company, if you can call it that. You'd think at least in the middle of the swamp you'd get some privacy, you know?", sourceObjectiveStatus = "unverified-source-field" }
quests[27341] = { id = 27341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Shore", description = "It's them or us, {class}. Only one of us can command this beach.\n\nNorth of here you'll see a small hill with a commanding view of the shoreline. Whoever controls that hill will have the upper hand up and down the shore!\n\nI need to know what the current situation is. Scout the beach head control point, marked by that enormous flag, and return to me.\n\nYou don't have to try to capture it, unless you're spoiling for a fight...", sourceObjective = "Scout the Beach Head Control Point on the Twilight Shore. You don't need to capture it, but doing so will give your side a combat advantage and flag you for PvP.", progress = "What's the word out there, {name}?", completion = "That's the lay of the land, soldier. If you're having trouble fighting here on the coast, you might consider pitching in and helping us take and hold that hill.", sourceObjectiveStatus = "unverified-source-field" }
quests[27342] = { id = 27342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Time, All Will Be Revealed", description = "The Dark Lady has sent you and Arthura here for a very specific purpose. Before I tell you more, we must make preparations.\n\nHead east into the forest of Gilneas and search near the trees and rocks of the region for a special plant known as wolfsbane. Gather as much of the wolfsbane as you can carry and return to me.\n\nOur mission here goes far beyond the scope of the battlefield, {name}. In time, all will be revealed.", sourceObjective = "Collect 6 Wolfsbane.", progress = "Did you gather the wolfsbane?", completion = "<Belmont takes the wolfsbane from you.>\n\nGood. Now just do as Forward Commander Onslaught commands. Try your best to fit in with the rest of the soldiers. We don't want the Gilneas Liberation Front to get suspicious.\n\nOh, you didn't know they were watching us? Right now there are five different worgen spies looking down on our position. Just be calm and follow orders. I'll let you know when we are ready to proceed.", sourceObjectiveStatus = "unverified-source-field" }
quests[27343] = { id = 27343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of the Light", description = "I have been watching your progress, {name}, and I can only conclude that the Light shines brightly upon you. You are becoming an exemplary {class}.\n\nTo honor your dedication, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe materials to make your weapon are unique, and only found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Do you have the materials for your weapon?", completion = "Lord Grayson has told me much about you and your dedication to the Light and the Alliance. It will be a great honor to craft a hammer for you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27344] = { id = 27344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Well-Earned Reward", description = "I am not the only one impressed by your progress {name}. Your mastery of bow and pet and your dedication to the Alliance have reached the ears of King Wrynn.\n\nIn recognition of your service, the king has commissioned the royal bowyer to craft a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is home to the unique materials needed for your weapon. Travel there and obtain the scope from Lord Godfrey's gun, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Godfrey's Crystal Scope from Lord Godfrey, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Who knew that cursed old keep hid such valuable items? I'll be honored to craft them into a fine weapon for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27345] = { id = 27345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The F.C.D.", description = "Communications are down with all of our frontline outposts, {name}. As of right now I don't have a damn clue as to the status of our troops in Gilneas. We need to re-establish communications.\n\nI need you to head west into the headlands and find our outpost on the coast. By now the soldiers there are likely all dead, but their F.C.D. might be operational. Grab the device and get back to me.", sourceObjective = "Recover the Forsaken Communication Device.", progress = "Recover the F.C.D.", completion = "With this device I will be able to communicate with you in the field. Now to check the rest of our frontline outposts.", sourceObjectiveStatus = "unverified-source-field" }
quests[27346] = { id = 27346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zeppelin Crash", description = "Not long ago, a goblin zeppelin crashed to the east. A representative of the Steamwheedle Cartel passed through here a few days ago.\n\nShe was looking for information about the zeppelin's cargo and its pilot, Beezil, but none of us really got a good look at the crash. I doubt she'll be able to clean up after the wreck by herself, much less recover whatever cargo the vessel might have carried.\n\nIf you have time, you may want to check up on her out at Beezil's Wreck, due east of here, near the mountains.", sourceObjective = "Speak with Moxie Steelgrille at Beezil's Wreck.", completion = "So those hermit mages sent you? How can I be sure that I can trust you?\n\nI suppose I can use the help. There's not much here a mage would be interested in, anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[27347] = { id = 27347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrosion Prevention", description = "Just look at this area! It's swarming with oozes. If I don't find some way to keep them under control, they'll corrode the wreckage and the zeppelin's cargo!\n\nI can't go back empty-handed, {class}! Help me dissolve these oozes before they've digested everything!\n\nThis device, when powered, will concentrate energy on the slimes, causing them to explode. The zeppelin's fragmented power core should power the device. The one near the main crash works all the time, but the others flicker on and off.", sourceObjective = "Moxie Steelgrille wants you to dissolve 10 oozes and report back to her at Beezil's Wreck.", progress = "Did you make any progress against those oozes?", completion = "Well, it does look a little cleaner out there...\n\nI suppose it's time to get down to the business of salvaging this wreckage.", sourceObjectiveStatus = "unverified-source-field" }
quests[27348] = { id = 27348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secure the Cargo!", description = "This zeppelin was carrying six months' worth of supplies to us at Mudsprocket! Sure, they've been able to barter for some of what they need, but they won't hold out forever.\n\nI've been sent out here to recover what I can of the cargo, but the wreckage is scattered all over the marsh in this area. I'm sure a lot of the cargo didn't survive the crash, but are you willing to help me recover what we can?", sourceObjective = "Moxie Steelgrille at Beezil's Wreck wants you to recover 8 pieces of Zeppelin Cargo.", progress = "<Moxie looks frantic with worry.>\n\nDid the cargo survive? Did you find any of it?", completion = "Wow! You certainly found a lot more than I expected would be out there. I'm not sure how much Drazzit thought we were going to find out here, but he's going to have to be happy with this for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27349] = { id = 27349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break in Communications: Dreadwatch Outpost", description = "I'm not gonna lie to you, {name}. What I'm about to ask you to do is suicide. Chance of failure is about 95%.\n\nAll communication from Dreadwatch Outpost has been severed. With the worgen constantly rushing us we have no means by which to get to Dreadwatch to check on our soldiers. I need you to head south to the outpost and check on our soldiers. I'll keep in contact through the Forsaken communication device - F.C.D. - from here on out.\n\nKEEP CLEAR OF THE MAIN ROAD.", sourceObjective = "Investigate Dreadwatch Outpost.", progress = "Status?", completion = "<The F.C.D. crackles with static.>\n\nDreadwatch is lost? This is bad, {name}. Real bad.\n\nIf Dreadwatch is compromised it means we've lost Gilneas City.", sourceObjectiveStatus = "unverified-source-field" }
quests[27350] = { id = 27350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break in Communications: Rutsak's Guard", description = "<The F.C.D. hums.>\n\nOur next outpost is Rutsak's Guard, located due east of Dreadwatch. Make your way to Rutsak's while avoiding the worgen rushers, {name}. You don't want to deal with those monsters by yourself.\n\nIf you make it there in one piece, look for Captain Rutsak.\n\nJust be prepared for the worst.", sourceObjective = "Find Captain Rutsak at Rutsak's Guard in the Ruins of Gilneas.", completion = "Th... Af... After we lost Gilneas City, the port fell.\n\nHU... HUM... HUMANS ARE HERE! Reinforcements from Stormwind! They slaughtered my men. Left me alive to witness their strength. To tell high command... To tell them that the 7th Legion are here...", sourceObjectiveStatus = "unverified-source-field" }
quests[27351] = { id = 27351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Reward", description = "SI:7 has been watching your progress with interest. You service to the Alliance is well-known and tales of your deeds have reached the king's ears.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is home to the exotic materials for your weapon. Travel there and recover Commander Springvale's sharpening stone, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Springvale's Sharpening Stone from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "It was quite an honor to receive the commission for your weapon, {name}. When Tony mentioned using so many exotic materials, I had my doubts, but it seems you managed to find them all. This will be a fine reward for all you've done for the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27352] = { id = 27352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liquid Gold", description = "As the Scourge swept through Stratholme like a plague, the Knights of the Silver Hand manufactured holy water to use against the invaders. They stored it inside small crates along with other vital supplies, and distributed them throughout the city. Unfortunately, the citizens turned into Scourge reinforcements before the supplies could ever be used!\n\nThese supply crates will prove extremely useful to our efforts. Bring me a vial of Stratholme Holy Water, we need to have it replicated in mass quantities.", sourceObjective = "Find a vial of Stratholme Holy Water.", progress = "Is that the vial of Stratholme Holy Water?\n\nWait, is that just regular water? Don't play games with ol' Stonebruiser!", completion = "Excellent! I think the holy water will prove devastating in large volumes.", sourceObjectiveStatus = "unverified-source-field" }
quests[27353] = { id = 27353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of the Elements", description = "Your talent has attracted much attention in shamanic circles, {name}. Word of your mastery of the elements and dedication to the Alliance has even reached the palace.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe materials for your weapon can only be found in Silverpine Forest's cursed Shadowfang Keep. Travel there and retrieve Lord Walden's talisman, the Book of Lost Souls, and the essence of the ghosts haunting the castle.", sourceObjective = "Go to Shadowfang Keep and obtain Walden's Talisman, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I have rarely had the chance to work with such exotic materials, but even I can sense the power residing within them. I will have the honor of crafting an incredible weapon for you, {name}. The farseer did not underestimate your abilities when she told me about you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27354] = { id = 27354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Arcane", description = "You have proven yourself a brilliant student and a dedicated servant of the Alliance. Word of your accomplishments has even reached the ears of the king.\n\nIn recognition of your service, King Wrynn has commissioned the royal enchanter to create a special weapon.\n\nThe materials required for your staff are found only in Silverpine Forest's cursed Shadowfang Keep. Travel there and find a lost heirloom of the Silverlaine family, a supply of moontouched wood, and the essence of the ghosts haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Silverlaine's Enchanted Crystal from Baron Silverlaine, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, I have been expecting you, {name}. Maginor Dumas has spoken highly of you and the royal commission only confirms his words. It is an honor to be able to craft a staff for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[27355] = { id = 27355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Boon for the Powerful", description = "The king is finally beginning to take note of our power and our value to the Alliance, thanks to your deeds. Perhaps they are beginning to accept our kind.\n\nKing Wrynn has commissioned the royal enchanter to create a powerful weapon in recognition of your achievements.\n\nThe materials you will need come from Silverpine Forest's Shadowfang Keep. Travel there and obtain the tenebrous orb held by Lord Godfrey, the Book of Lost Souls, and the essence of the ghosts haunting the castle.", sourceObjective = "Go to Shadowfang Keep and obtain the Tenebrous Orb from Lord Godfrey, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I won't ask what you had to do to come by such rare and powerful materials, but I'm glad to have the chance to work with them. Your weapon will be magnificent!", sourceObjectiveStatus = "unverified-source-field" }
quests[27356] = { id = 27356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Circle's Future", description = "The Cenarion Circle is pleased with your progress, {name}. You are a credit to all druids and we look to you and your peers as the future of of our brotherhood.\n\nThe circle has decided to honor you with the creation of unique staff.\n\nThe rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden's collection of elixirs, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain Walden's Elixirs from Lord Walden, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your staff?", completion = "Ah, you must be the {class} Loganaar was talking about. It is a pleasure to finally meet you. Loganaar and other members of the circle speak highly of you. It will be an honor to make a weapon for such a {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27357] = { id = 27357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive Bride", description = "Of course! Lakota Windsong! Why didn't I think of this before?\n\nArnak kidnapped Lakota years ago and tried to force her into being his bride. She managed to escape, but in the chaos of the recent attack on Freewind Post, he took her again.\n\nShe has to be around here somewhere. She's become quite the mystic in recent years. I'm guessing she'll know what to do with these tauren artifacts.", sourceObjective = "Speak with Lakota Windsong at Darkcloud Pinnacle in Thousand Needles.", completion = "It is embarrassing to have been kidnapped by Arnak again. I heard the fighting outside. Did you kill him?\n\n<The shaman looks sad for just a moment.>\n\nI am happy to be free once more. Now, how can I help you, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27358] = { id = 27358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive Bride", description = "Lakota Windsong! Why did I not think of this before?\n\nArnak kidnapped Lakota years ago and tried to force her to be his bride. With help, she was able to escape, but in the chaos of the recent attack on Freewind Post, he took her again.\n\nShe must be near. She has become quite the shaman in recent years. I am sure that she will understand the significance of the rattle, the writ, and the drums.", sourceObjective = "Speak with Lakota Windsong at Darkcloud Pinnacle in Thousand Needles.", completion = "It is embarrassing to have been kidnapped by Arnak again. I heard the fighting outside. Did you kill him?\n\n<The shaman looks sad for just a moment.>\n\nI am happy to be free once more. Now, how can I help you, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27359] = { id = 27359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Reinforcements", description = "The Scourge have some sort of ward in place that's preventing me from opening a portal so that our reinforcements can help us take the city! It's like a neverending screaming inside of my head! Agh!\n\nI'm doing all I can to retain my sanity from that noise with this barrier. My best guess is that the banshees are maintaining the defense. If you could bring me some of their essences, I think I can use them to counteract the ward and get our boys in here!", sourceObjective = "Obtain 4 Banshee Essences.", progress = "Were you able to obtain the essences? Be careful, they're deadly spellcasters.", completion = "Oh my... the banshees are very tortured souls indeed. Merely holding their essence is emotionally painful...\n\nEnough of that for now. I'll get to work on counteracting their magic, then we'll have a portal up and running in no time. Stratholme will be ours soon, I just know it.", sourceObjectiveStatus = "unverified-source-field" }
quests[27360] = { id = 27360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Our Soldiers", description = "7th Legion... They rushed us in the dead of the night. Their captain barked orders as the submariners slaughtered my men. Then he came to me, put his face in mine, and said something I'll never forget:\n\n\"The name's Master Sergeant Pietro Zaren, officer in the 7th Legion. When you see your soldiers being slaughtered in your nightmares - if you even still dream - remember my name and tremble.\"\n\nAvenge my soldiers! Kill the 7th Legion occupying the Cathedral Quarter of Gilneas City, southwest of here.", sourceObjective = "Kill 10 7th Legion Submariners.", completion = "Though we were shamed in battle, the enemy was not victorious. I will not soon forget this, {name}.\n\nIf I make it back to Silverpine I will likely retire from the service. War is not in my blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[27361] = { id = 27361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored of the Light", description = "The Light truly shines in you and your dedication to the Alliance, {name}. You serve as an example to your fellow priests and comrades in arms.\n\nIn recognition of your deeds, King Wrynn has commissioned the royal enchanter to create a special staff.\n\nThe materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears.", sourceObjectiveStatus = "unverified-source-field" }
quests[27362] = { id = 27362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Favored of Elune", description = "You are a true servant of Elune, an example to our people, and stalwart servant of the Alliance. The Temple of the Moon and the court of Stormwind wish to honor your achievements.\n\nWe have commissioned the royal enchanter to create a staff for you.\n\nThe materials for your staff can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears.", sourceObjectiveStatus = "unverified-source-field" }
quests[27363] = { id = 27363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Budding Young Surgeon", description = "You have shown yourself to be a capable priest and a credit to the people of Gnomeregan. The high tinker and the king of Stormwind wish to honor your contribution to the Alliance.\n\nThey have commissioned the royal enchanter to create a special staff.\n\nThe materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears.", sourceObjectiveStatus = "unverified-source-field" }
quests[27364] = { id = 27364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Whose Orders?", description = "<The F.C.D. buzzes.>\n\nThe 7th Legion are an elite special ops regiment. They've been there, behind the scenes, for almost every major offensive and military engagement the Alliance has ever done. This is bad news. How did they get past our warships? And on whose orders are they here?\n\nWe need to get our hands on their orders. This Pietro character will undoubtedly have vital information. Find him at the Cathedral Quarter in Gilneas City and take him out. Search his corpse for clues.", sourceObjective = "Recover the Orders from High Command.", progress = "Status?", completion = "<The F.C.D. crackles with electricity.>\n\nAn Alliance armada is en route? How could this have happened?\n\n<Forward Commander Onslaught cuts out for a moment. You hear worgen howling in the background.>\n\nYou've got to hurry, {name}. We're being overrun up here at Forward Command.", sourceObjectiveStatus = "unverified-source-field" }
quests[27365] = { id = 27365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fitting Weapon", description = "From your earliest days, your trainers always knew you would make your mark on the Horde. You have fought bravely and given our enemies reason to fear.\n\nAs a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost Silverlaine family sword, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", sourceObjective = "Go to Shadowfang Keep and obtain the Silverlaine Family Sword from Baron Silverlaine, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Grezz Ragefist told me to expect you. Those materials will make a fine sword. Always use it for the glory of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27366] = { id = 27366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landgrab", description = "The Horde's Axebite Marines are all up in my precious, precious beach.\n\n<The Lieutenant points north, along the shore.>\n\nKill them.", sourceObjective = "Slay 12 Axebite Marines on the Twilight Shores in Twilight Highlands.", progress = "You're still alive, {name}.\n\nAre they?", completion = "Dead? By the dozen?\n\nIt's a start, {class}. It's a start.", sourceObjectiveStatus = "unverified-source-field" }
quests[27367] = { id = 27367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin Goldbraids", description = "I love my boys, don't get me wrong.  But I TOLD them that I needed FIVE MINUTES to water and brush the horses, and what did they do?  They made a stupid bet with each other and ran off!  I should have known better... this always happens.\n\nGidwin's the short one.  He headed north, along the river.  If you're headed that direction, would you tell him to come back?  We've got to get to Light's Hope Chapel, and I'm not against leaving without him.", sourceObjective = "Find Gidwin Goldbraids in Eastern Plaguelands.", completion = "Tarenar?  Is that you?\n\nWhoever you are, would you mind helping me out of this thing?", sourceObjectiveStatus = "unverified-source-field" }
quests[27368] = { id = 27368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Encased", description = "You should have seen me fight!  I must have killed six of those beasts, when...\n\nOh wait, you can count the bodies, can't you?  OK, fine.  I killed four of them, when the fifth one shot me with this web.  To make things even worse... when he blasted me with web juice, my mouth was open!\n\nI can't seem to break these webs, and I doubt you'll be able to, either.  No, you'll have to get some of the stomach juice from those undead spider-things.  That'll do the trick.", sourceObjective = "Obtain 8 vials of Crypt Bile from nerubians in Terrorweb Tunnel.", progress = "Oh boy... Fiona is going to be madder than a wet harpy.  You'd better hurry.", completion = "You're back?!  Thank the Light!\n\nBefore you throw that acid on me, I need to ask: Are you the guy who was here before, or are you one of those eight-legged cowards?  I need to know whether or not I should smack you on my way out.", sourceObjectiveStatus = "unverified-source-field" }
quests[27369] = { id = 27369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greasing the Wheel", description = "Sorry about that.  I was pretty sure you were one of those spider-beasts, doing a bad {race} impression.\n\nHow do you do?  Gidwin Goldbraids, at your service.  I'm in a bit of a hurry back to my caravan, but I was wondering if you might do me one last favor?  My pal Fiona runs a small shop, and she could probably use some of these herbs that grow along the river shore.\n\nI'm thinking if we give her some nice herbs, she'll be MUCH less likely to murder me.  That's the plan, anyway.", sourceObjective = "Loot 10 Banshee's Bells from the shore of the Thondroril River.", progress = "Giddy's got you mixed up in all of this now?", completion = "I'll tear that pint-size paladin to shreds before he... wait a minute are those Banshee's Bells?  You brought these for me?\n\nOh, Gidwin asked you to get them for me!  That sweet little guy.  Alright.  He's off the hook for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[27370] = { id = 27370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenar Sunstrike", description = "As soon as we stopped, they made a bet about \"who could kill the most undead in five minutes.\"\n\nIt's been an hour, and I'm still waiting for them to come back.\n\nI saw Tarenar run off to the southeast.  Unfortunately, I can't leave the caravan here by itself.  If you end up traveling in that direction, could you find him and send him back to me?", sourceObjective = "Find Tarenar Sunstrike at Death's Step in Eastern Plaguelands.", completion = "I've found them, {race}.  The Scourge.  How I've longed for this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[27371] = { id = 27371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What I Do Best", description = "I remember when I was young, I would sneak off into the Ghostlands and just beat up zombies for hours on end.  Nobody even PAID me.  I just did it.\n\nNow, look in front of you.  Those are some serious zombies.  I was just about to start beating them up, too.  Care to join me?", sourceObjective = "Kill 5 Death's Step Miscreations at Death's Step in Eastern Plaguelands.", completion = "Five should be good enough.\n\nYikes, look at the time!  I need to head back to camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[27372] = { id = 27372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Fiona", description = "My traveling companion, Fiona, runs a small vendor's shop out of her caravan.  She and I, along with our friend Gidwin, are all on our way to Light's Hope Chapel.  I'm sure you can join us, if you like... though Fiona might be a little mad at me.\n\nFiona always forgets why she's mad if you give her a gift.  Kill some of the plaguehounds north of here, then bring their blood to Fiona at the caravan, down by the river.  She'll love it.  We'll talk again there.", sourceObjective = "Obtain 10 samples of Plaguehound Blood.", progress = "I should have guessed it.  Tarenar made you get me a gift?  That thoughtless idiot!\n\nUmm... what was the gift, anyhow?", completion = "Why, this is exactly what I needed!  Fine, I'll forgive Tarenar for running off.\n\n{name}, you're welcome to join us anytime.", sourceObjectiveStatus = "unverified-source-field" }
quests[27373] = { id = 27373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward, to Light's Hope Chapel", description = "Now that the boys are back, we can head out.  You headed east?\n\nPlease, join us!  I insist!  Yesterday, we were in the Menders' Stead, and I was telling Tarenar, \"We have two paladins and a shopkeeper, but you know what we really need?  A {class}!\"\n\nDon't look at me that way!  I'm serious!  Come on, hop in the cart.", sourceObjective = "Board Fiona's Caravan at the Thondroril River in Eastern Plaguelands.", completion = "Hope the ride wasn't too bumpy for you.\n\nHave a look around the tower while the horses rest.  It's no Light's Hope Chapel, but I'm sure you can find some way to keep yourself busy.", sourceObjectiveStatus = "unverified-source-field" }
quests[27374] = { id = 27374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maw of Madness", description = "I can't believe it, {name}. Me own son - me own flesh and blood! Throwing his lot in with those fiends from the Twilight's Hammer. Did you see what he became when he tried to destroy the wedding? Oh ... why? Why?\n\nIt's that beast, {name}. The enormous mouth emerging from the earth to our west. \"The Maw of Madness!\" My son said it spoke to him, but I thought it was just nightmares.\n\nThe Earthen Ring is trying to destroy it. Go to Earthcaller Torunscar, west of here, and see how you can help!", sourceObjective = "Speak to Earthcaller Torunscar at the Ring of the Elements.", completion = "Welcome, brotha. You've chosen a harsh time to be joinin' us, but that is to our fortune. We could use ya help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27375] = { id = 27375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weeping Wound", description = "A beast, {name}! I saw a beast. A great maw, an even greater hungering. They can't possibly know what they unleashed.\n\nIt is here. Its terrible shapeless body is erupting right into the Highlands.\n\nI saw you in my vision, {name}. You struggle with the Earthen Ring to contain the beast. You will face the darkness.\n\nGo now, before the beast grows in power. Speak to Earthcaller Torunscar at the Circle of the Elements, northwest of here atop the ridge beyond the ruined Drakgor Encampment. Hurry!", sourceObjective = "Speak with Earthcaller Torunscar at the Ring of the Elements.", completion = "Welcome, brotha. You've chosen a harsh time to be joinin' us, but that is to our fortune. We could use ya help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27376] = { id = 27376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Maw of Iso'rath", description = "We are ready to attack the beast. First, we need to destroy it's tentacles, then Yevaa will perform a ritual to summon a powerful fire elemental that we will drop into its maw.\n\nI want you to fly out with our first group attack. Hold steady until an opportunity presents itself, then join the battle with the rest of the shaman in cutting the tentacles down.\n\nTake any one of the gryphons when you're ready to join the assault.", sourceObjective = "Mount a gryphon to join the attack on Iso'rath.", progress = "You were to meet at the gryphons. Please stick to the plan.", completion = "The tentacles swept us off of our gryphons as well! They were far more nimble than we anticipated.\n\nNo matter. We were prepared for this possibility. I can summon the elemental from here if you can keep me safe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27377] = { id = 27377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devoured", description = "We knew this was a possibility, but we had no idea how the beast would defend itself. Iso'rath's body is reacting quickly to our threat.\n\nI can complete the summoning from here, but only if you can hold back Iso'rath's defenses. Keep them busy! We will survive this!", sourceObjective = "Defend yourself and Earthcaller Yevaa from Iso'rath's bodily defenses.", completion = "I've brought you back from the brink of death, hero!\n\nDeathwing is upon us! We need your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[27378] = { id = 27378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Worldbreaker", description = "There's no time! Deathwing struck before we could form against him. If you do not stop him, the Earthen Ring will end this day!", sourceObjective = "Defeat Deathwing, the Aspect of Death.", completion = "You're awake! Thank the elements. I'd almost lost all hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[27379] = { id = 27379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terrors of Iso'rath", description = "We need you! You were stuck in some kind of nightmare. So are many of the other shaman.\n\nIt doesn't matter... our plan is falling apart. Some of our shaman are channeling protective auras that should combat the digestive juices and keep you alive, but we need you to rescue the other shaman from the tentacles.  We won't be able to defeat Iso'rath without them!\n\nDon't stay out in the stomach without the other shaman for too long or you'll be digested alive!", sourceObjective = "Rescue Hargoth Dimblaze, Earthmender Duarn, Stormcaller Jalara, and Stormcaller Mylra.\n\nReturn to the safety of the other shaman if Iso'rath's defenses are eating away at you.", progress = "The battle is not over. The shaman within Iso'rath need you!", completion = "United with the Earthen Ring, we can survive the horrors of Iso'rath. Now it is time to turn our vengeance upon him!", sourceObjectiveStatus = "unverified-source-field" }
quests[27380] = { id = 27380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare", description = "Iso'rath's brain is revealed! The shaman you've saved should keep you somewhat safe amidst his defenses.\n\nStrike at the brain and destroy Iso'rath!", sourceObjective = "Destroy the Brain of Iso'rath.", completion = "You saved many of my closest allies today, {name}. I can only imagine what horrors you witnessed within Iso'rath, but you have the thanks of all of the Earthen Ring.", sourceObjectiveStatus = "unverified-source-field" }
